window.LAW_DATA = {"id": "idara-mahaleya", "title": "قانون الإدارة المحلية", "title_en": "LOCAL GOVERNANCE", "cat": "عمل وإداري", "icon": "🏙️", "desc": "القانون رقم 43 لسنة 1979 — تنظيم المحليات والمجالس الشعبية والتنفيذية.", "article_count": 170, "articles": [{"number": "الاولى", "chapter": "", "text": "يعمل بأحكام القانون المرافق بشأن نظام الإدارة المحلية . أستبدلت \" الحكم المحلي \" و\"الوزير المختص بالحكم المحلي بعبارة \" الإدارة المحلية\" بالقانون رقم 145 لسنة 1988"}, {"number": "الثانية", "chapter": "", "text": "يستمر العمل بأحكام اللوائح والقرارات التنظيمية العامة السارية فى تاريخ العمل بهذا القانون فيما لا يتعارض مع أحكام القانون المرافق ."}, {"number": "الثالثة", "chapter": "", "text": "تتخذ الإجراءات اللازمة لنقل الاعتمادات الواردة بالموازنة العامة للدولة والخاصة بالمرافق التى نقل الاختصاص بشأنها بمقتضى هذا القانون إلى وحدات الإدارة المحلية ، إلى موازنات هذه الوحدات اعتبارا من السنة المالية 1980 ، ومع مراعاة أحكام المادة 142 من القانون المرافق ."}, {"number": "الرابعة", "chapter": "", "text": "يعمل بأحكام قرار الوزير المختص بالإدارة المحلية رقم 239 لسنة 1971 والقرارات المكملة له بشأن الموارد المالية والرسوم المحلية وذلك حتى تحدد هذه الموارد والرسوم طبقا للأحكام الواردة فى القانون المرافق . ويجوز زيادة الرسوم المشار إليها بما لا يجاوز مثلى الفئات المنصوص عليها فى القرار المشار إليه وذلك بقرار من مجلس الوزراء بناء على عرض وزير المختص بالإدارة المحلية واقتراح المجلس الشعبى المحلى للمحافظة المختص . معدلة بالقانون رقم 145 لسنة 1988 ."}, {"number": "الخامسة", "chapter": "", "text": "تصدر بقرار من رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق خلال ثلاثة أشهر من تاريخ العمل بأحكامه ."}, {"number": "السادسة", "chapter": "", "text": "تستمر المجالس المحلية بتشكيلها الحالى إلى نهاية مدتها ، على أن تجرى الانتخابات لتشكيل المجالس الجديدة ، وفقا لأحكام القانون المرافق ، خلال الستين يوما السابقة على انتهاء مدة المجالس الحالية ."}, {"number": "السابعة", "chapter": "", "text": "فيما عدا ما نص عليه فى المواد 4، 5 ، 6 من القانون 107 لسنة 1976 بإنشاء صندوق تمويل مشروعات الإسكان الاقتصادى ، يلغى الصندوق المشار إليه وتوزع حصيلة موارد هذا الصندوق على المحافظات وفقا للقواعد والنسب التى يضعها مجلس المحافظين بالاتفاق مع وزيرى المالية والإسكان."}, {"number": "الثامنة", "chapter": "", "text": "يستبدل بعبارتى \" المجلس المحلى \" و\" المجالس المحلية \" أينما وردتا فى القوانين واللوائح عبارتا \"المجلس الشعبى المحلى\" و\"المجالس الشعبية المحلية \" . ويلغى القانون رقم 52 لسنة 1975 بإصدار قانون نظام الحكم المحلى كما يلغى كل نص يخالف أحكام القانون المرافق ."}, {"number": "التاسعة", "chapter": "", "text": "ينشر هذا القرار فى الجريدة الرسمية ، وتكون له قوة القانون ، ويعمل به من تاريخ نشره . صدر برياسة الجمهورية فى 25 رجب سنة 1399 20 يونيه سنة 1979 . أنور السادات قانون نظام الإدارة المحلية"}, {"number": "1", "chapter": "الفصل الأول", "text": "وحدات الإدارة المحلية هى المحافظات والمراكز والمدن والأحياء والقرى ، ويكون لكل منها الشخصية الاعتبارية ويتم إنشاء هذه الوحدات وتحديد نطاقها وتغيير أسمائها وإلغائها على النحو التالى : (أ) المحافظات : بقرار من رئيس الجمهورية ويجوز أن يكون نطاق المحافظة مدينة واحدة . (ب) المراكز والمدن والأحياء : بقرار من رئيس مجلس الوزراء بعد موافقة المجلس الشعبى المحلى للمحافظة . (ج) القرى : بقرار من المحافظ بناء على اقتراح المجلس الشعبى المحلى للمركز المختص وموافقة المجلس الشعبى للمحافظة. ويجوز أن يشمل نطاق الوحدة المحلية للقرية مجموعة من القرى المتجاورة ويكون للمحافظات ذات المدينة الواحدة الموارد والاختصاصات المقررة للمحافظة والمدينة . ويباشر المركز أو الحى بحسب الأحوال اختصاصات الوحدة المحلية بالقرية بالنسبة للقرى التى لا تدخل فى نطاق وحدات محلية قروية . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "2", "chapter": "الفصل الأول", "text": "تتولى وحدات الإدارة المحلية فى حدود السياسة العامة والخطة العامة للدولة إنشاء وإدارة جميع المرافق العامة الواقعة فى دائرتها . كما تتولى هذه الوحدات كل فى نطاق اختصاصها جميع الاختصاصات التى تتولاها الوزارات بمقتضى القوانين اللوائح المعمول بها وذلك فيما عدا المرافق القومية أو ذات الطبيعة الخاصة التى يصدر بها قرار من رئيس الجمهورية ، وتحدد اللائحة التنفيذية المرافق التى تتولى المحافظات إنشاءها وإدارتها والمرافق التى تتولى إنشاءها وإدارتها الوحدات الأخرى للإدارة المحلية . كما تبين اللائحة ما تباشره كل من المحافظات وباقى الوحدات من الاختصاصات المنصوص عليها فى هذه المادة وتباشر المحافظات جميع الاختصاصات المتعلقة بالمرافق العامة التى لا تختص بها الوحدات المحلية الأخرى . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "3", "chapter": "الفصل الأول", "text": "يكون لكل وحدة من وحدات الإدارة المحلية مجلس شعبى محلى يشكل من أعضاء يتم انتخابهم عن طريق الانتخاب المباشر السرى العام وفقا لأحكام هذا القانون ،على أن يكون نصف عدد الأعضاء على الأقل من العمال والفلاحين ، وذلك طبقا لتعريف العامل والفلاح المنصوص عليه فى القانون رقم 38 لسنة 1972 فى شأن مجلس الشعب. ولا يخل إنشاء وحدة جديدة من وحدات الإدارة المحلية أو تعديل نطاقها أو إلغاؤها بتشكيل أى من المجالس الشعبية المحلية القائمة وذلك إلى أن تنتهى مدتها . ويمثل المجلس الشعبى المحلى رئيسه أمام القضاء وفى مواجهة الغير . مستبدلة بالقانون رقم 145 لسنة 1988"}, {"number": "4", "chapter": "الفصل الأول", "text": "يمثل المحافظة محافظها ، كما يمثل كل وحدة من وحدات الإدارة المحلية الأخرى رئيسها وذلك أمام القضاء وفى مواجهة الغير."}, {"number": "4 مكرر", "chapter": "الفصل الأول", "text": "يجوز بقرار من رئيس الجمهورية بعد موافقة مجلس الوزراء وبناء على اقتراح الوزير المختص بالإدارة المحلية ، إصدار تنظيم خاص لبعض المدن ذات الأهمية الخاصة يهدف إلى تنميتها والنهوض بمرافقها. مضافة بالقانون رقم 9 لسنة 1989."}, {"number": "5", "chapter": "الفصل الثانى", "text": "يشكل مجلس أعلى للإدارة المحلية برئاسة رئيس مجلس الوزراء أو من ينيبه وعضوية : الوزير المختص بالإدارة المحلية . المحافظين . رؤساء المجالس الشعبية المحلية للمحافظات . ولرئيس المجلس دعوة من يرى حضوره جلسات المجلس من الوزراء أو غيرهم . ويجتمع المجلس بدعوة من رئيسه بصفة دورية فى المواعيد التى تحددها اللائحة التنفيذية ويتولى النظر فى كل ما يتعلق بنظام الإدارة المحلية من حيث دعمه وتطويره واقتراح القوانين واللوائح والقرارات ذات التأثير على المجتمع المحلى . مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "6", "chapter": "الفصل الثانى", "text": "تتبع الأمانة العامة للإدارة المحلية الوزير المختص بالإدارة المحلية وتتولى الشئون المشتركة للوحدات المحلية وكذلك دراسة وبحث الموضوعات الواردة من تلك الوحدات . كما تتولى تنظيم الاشتراك فى المؤتمرات الدولية والمحلية المتعلقة بالإدارة المحلية وشئون التدريب للعاملين بالأجهزة المحلية ، وتقديم المشورة لوحدات الإدارة المحلية والعمل على توحيد الرأى القانونى الصادر فى المسائل المتعلقة بشئون الإدارة المحلية وتعميم التجارب الرائدة فى بعض المحافظات كما تقوم بمعاونة الوزير المختص بالإدارة المحلية فى إعداد الدراسات والأبحاث المتعلقة بالموضوعات التى يعرضها على مجلس الوزراء والمجلس الأعلى للإدارة المحلية وإبلاغ القرارات الى الوحدات المحلية ومتابعة تنفيذها . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "7", "chapter": "الفصل الثالث", "text": "تقسم جمهورية مصر العربية إلى أقاليم اقتصادية يضم كل منها محافظة أو أكثر ويكون لكل إقليم عاصمة وذلك على النحو الذى يصدر به قرار من رئيس الجمهورية ."}, {"number": "8", "chapter": "الفصل الثالث", "text": "ينشأ بكل إقليم اقتصادى لجنة للتخطيط الاقليمى تشكل على النحو التالى : - محافظ الإقليم ، وله الرئاسة ويكون بالتناوب سنويا من بين محافظى المحافظات المكونة للإقليم . - محافظو المحافظات المكونة للإقليم . - رؤساء المجالس الشعبية المحلية للمحافظات المكونة للإقليم. - رئيس هيئة التخطيط الاقليمى ..................... أمينا عاما للجنة . - ممثلو الوزارات المختصة ويصدر باختيار كل منهم قرار من الوزير المختص . وتختص هذه اللجنة بما يأتى : 1- التنسيق بين خطط المحافظات وإقرار الاولويات التى تقترحها هيئة التخطيط الاقليمى والتى تتخذ أساسا فى وضع بدائل لخطة الإقليم وذلك على ضوء الموارد المتاحة محليا ومركزيا . 2- النظر فى التقارير الدورية لمتابعة تنفيذ الخطة ودراسة التعديلات التى تقترحها هيئة التخطيط الإقليمى فى الخطة وفقا للظروف التى تواجه تنفيذها ، ويعرض ما تصدره اللجنة من التوصيات على المجلس الأعلى للإدارة المحلية. مستبدلة بالقانون رقم 145 لسنة 1988."}, {"number": "9", "chapter": "الفصل الثالث", "text": "تنشأ بكل من الأقاليم الاقتصادية هيئة للتخطيط الاقليمى تتبع وزير التخطيط ويصدر بتنظيمها وتحديد العلاقة بينها وبين إدارات التخطيط والمتابعة بالمحافظات قرار من وزير التخطيط بالاتفاق مع محافظ الإقليم. وتختص بالآتى : 1- القيام بالبحوث والدراسات اللازمة لتحديد إمكانيات وموارد الإقليم الطبيعية والبشرية ووسائل تطويرها واستخداماتها المثلى ، واقتراح المشروعات اللازمة للتنمية الاقتصادية والاجتماعية للإقليم . 2- القيام بإعداد الأجهزة الفنية اللازمة للقيام بالدراسات والبحوث وأعمال التخطيط على مستوى الإقليم ."}, {"number": "10", "chapter": "الفصل الأول", "text": "يشكل بكل محافظة مجلس شعبى محلى من أربعة أعضاء عن كل مركز أو قسم ادارى ، أحدهم على الأقل من النساء. ويكون تمثيل كل مركز أو قسم ادارى فى كل من محافظات منطقة القناة ومطروح والوادى الجديد وشمال سيناء وجنوب سيناء والبحر الأحمر بثمانية أعضاء أحدهم على الأقل من النساء . ويكون للمدينة ذات الطابع الخاص التى يصدر بتحديدها قرار من رئيس الجمهورية مجلس شعبى محلى عال يشكل طبقا لنص الفقرة الأولى من هذه المادة وتكون له كافة الصلاحيات المقررة للمجلس الشعبى المحلى للمحافظة المنصوص عليها فى هذا القانون . ويشكل المجلس الشعبى المحلى الأعلى للأقصر من الأعضاء الحاليين الذين يمثلون مدينة ومركز الأقصر فى المجلس الشعبى المحلى لمحافظة قنا ، وتعتبر عضويتهم سارية لحين انتهاء مدة المجالس الشعبية المحلية الحالية . معدلة بالقانون رقم 96 لسنة 2003."}, {"number": "11", "chapter": "الفصل الأول", "text": "ينتخب المجلس الشعبى المحلى للمحافظة من بين أعضائه فى أول اجتماع لدور الانعقاد العادى ولمدة هذا الدور رئيسا له ووكيلين ، على أن يكون أحدهما على الأقل من العمال أو الفلاحين . ويحل محل الرئيس عند غيابه كل من الوكيلين بالتناوب بينهما، وتكون الرئاسة لأكبر الأعضاء سنا إذا غاب الرئيس والوكيلان وإذا خلا مكان أحدهم انتخب المجلس من يحل محله الى نهاية مدته . الفرع الثانى اختصاصات المجالس الشعبية المحلية للمحافظات"}, {"number": "12", "chapter": "الفصل الأول", "text": "يتولى المجلس الشعبى المحلى للمحافظة فى حدود السياسة العامة للدولة الرقابة على مختلف المرافق والأعمال التى تدخل فى اختصاص المحافظة وفقا للمادة 2 من هذا القانون . وله أن يطلب عن طريق المحافظ أية بيانات تتعلق بنشاط الوحدات الأخرى الإنتاجية والاقتصادية وغيرها العاملة فى دائرة المحافظة كما يتولى الإشراف على تنفيذ الخطط الخاصة بالتنمية المحلية ومتابعتها وذلك على النحو المبين بالقانون واللائحة التنفيذية ويختص فى إطار الخطة العامة والموازنة المعتمدة وبمراعاة القوانين واللوائح بما يأتى : 1- إقرار مشروعات خطط التنمية الاقتصادية والاجتماعية ومشروع الموازنة السنوية للمحافظة ومتابعة تنفيذها والموافقة على مشروع الحساب الختامى . 2- تحديد وإقرار خطة المشاركة الشعبية بالجهود والامكانات الذاتية للمعاونة فى المشروعات المحلية 3- الموافقة على المشروعات العامة بما يفى بمتطلبات الإسكان والتشييد واقتراح مشروعات التخطيط العمرانى والتعمير . 4- الموافقة على إنشاء المرافق التى تعود بالنفع العام على المحافظة . 5- إقرار إنشاء المشروعات الإنتاجية المحلية وعلى الأخص المشروعات المتعلقة بالأمن الغذائى . 6- اقتراح فرض الضرائب ذات الطابع المحلى . 7- فرض الرسوم ذات الطابع المحلى وفقا لأحكام هذا القانون أو تعديلها أو تقصير أجل سريانها أو الإعفاء منها أو إلغاؤها بعد موافقة مجلس الوزراء . 8- دراسة وإعداد الخطط والبرامج الخاصة بمحو الأمية وتنظيم الأسرة فى نطاق المحافظة وتوفير الاحتياجات اللازمة ومتابعة تنفيذها . 9- إصدار التوصيات فى المقترحات والخطط المتعلقة بصيانة النظام والأمن المحلى . 10- إقرار القواعد العامة لنظام تعامل أجهزة المحافظة مع الجماهير فى كافة المجالات . 11- اقتراح إنشاء مناطق حرة وشركات استثمار مشتركة مع رأس مال عربى أو أجنبى وكذلك القيام بمشروعات مشتركة مع المحافظات الأخرى أو مع الوحدات المحلية أو الأشخاص الاعتبارية الأخرى بالمحافظة ، وذلك بعد موافقة جهات التخطيط المختصة وبمراعاة أحكام قانون استثمار المال العربى والأجنبى . 12- مباشرة الاختصاصات المتعلقة بمشروعات المجالس الشعبية المحلية فى نطاق المحافظة والتى لا تتمكن هذه المجالس من القيام بها . 13- الموافقة على تمثيل المجلس فى المؤتمرات الداخلية والاشتراك فى الندوات والمناقشات والدراسات التى تجريها السلطات المركزية وللمجلس الشعبى المحلى إصدار القرارات اللازمة لدعم ممارسته للاختصاصات المنصوص عليها فى هذه المادة ويبلغ رئيس المجلس قراراته وتوصياته واقتراحاته الى المحافظ خلال خمسة عشر يوما من تاريخ صدورها مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "13", "chapter": "الفصل الأول", "text": "يختص المجلس الشعبى المحلى للمحافظة بالنسبة للمجالس الشعبية المحلية الأخرى فى نطاق المحافظة وطبقا للقواعد المقررة فى هذا القانون ولائحته التنفيذية بما يأتى : (أ) الإشراف والرقابة على أعمال ونشاط هذه المجالس . (ب) التصديق أو الاعتراض على القرارات التى تصدر من هذه المجالس فى الحدود التى تقررها اللائحة التنفيذية . (ج) الموافقة على اقتراحات المجالس بإنشاء أو إلغاء الوحدات المحلية فى نطاق المحافظة أو تغيير أسمائها . ويبلغ رئيس المجلس قرارات المجلس الى المحافظ خلال خمسة عشر يوما من تاريخ صدورها . مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "14", "chapter": "الفصل الأول", "text": "يجوز للمجلس الشعبى المحلى للمحافظة التصرف بالمجان فى مال من أموالها الثابتة أو المنقولة أو تأجيره بإيجار إسمى أو بأقل من أجر المثل بقصد تحقيق غرض ذى نفع عام وذلك إذا كان التصرف أو التأجير لإحدى الوزارات أو المصالح الحكومية أو الهيئات العامة أو لأحد الأشخاص الاعتبارية العامة أو شركات القطاع العام والجمعيات والمؤسسات الخاصة ذات النفع العام . ومع عدم الإخلال بأحكام القوانين الخاصة بتملك الأجانب للعقارات يجوز للمجلس بعد موافقة رئيس مجلس الوزراء التصرف بالمجان أو التأجير بإيجار إسمى أو بأقل من أجر المثل لأحد الأشخاص الاعتبارية الخاصة أو لجهة أجنبية فى حدود خمسين ألف جنية فى السنة المالية الواحدة ولغرض ذى نفع عام ، ويجب موافقة مجلس الوزراء فيما يجاوز ذلك . وفى الأحوال التى يكون فيها التصرف أو التأجير وفقا لأحكام هذه المادة لأحد الأشخاص الاعتبارية الخاصة أو لجهة أجنبية ، يجب ألا تزيد مدة الإيجار على ثلاثين سنة يجوز تحديدها بقرار من مجلس الوزراء كما يجب بقاء الأموال موضوع التصرف أو التأجير مخصصة للغرض الذى تم التصرف أو التأجير من أجله ، فإذا زال هذا الغرض لأى سبب أو إذا أخل به المتصرف إليه أو المستأجر فى أى وقت ، اعتبر التصرف أو عقد الإيجار مفسوخا من تلقاء نفسه دون حاجة الى حكم قضائى أو إنذار وفى هذه الحالة تسترد المحافظة الأموال موضوع التصرف أو التأجير بالطريق الادارى. مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "15", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بحكم المادة 129 من القرار بقانون رقم 43 لسنة 1979 يجوز للمجلس الشعبى المحلى للمحافظة فى حدود الخطة والموازنة المعتمدة أن يقترض للقيام بمشروعات إنتاجية أو استثمارية لازمة للمحافظة أو الوحدات المحلية فى نطاقها بشرط ألا يجاوز حد المديونية 40 % من المجموع السنوى للإيرادات الذاتية للمحافظة أو للوحدة المحلية التى تنشأ فيها هذه المشروعات . ولا يجوز زيادة النسبة المشار إليها أو الاقتراض من جهة أجنبية إلا بموافقة رئيس مجلس الوزراء مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "16", "chapter": "الفصل الأول", "text": "للمجلس الشعبى المحلى للمحافظة فى حدود الموازنة المعتمدة أن يقرر تقديم المعونة المالية والفنية والإدارية للجهات ذات الأغراض الاجتماعية والخيرية والعلمية فى دائرة اختصاصه والموافقة على إقراض الجمعيات التعاونية ومساعدتها فنيا وإداريا بما يمكنها من القيام باختصاصاتها ."}, {"number": "17", "chapter": "الفصل الأول", "text": "يجوز للمجلس الشعبى المحلى للمحافظة بالاتفاق مع المحافظ ، أن يقرر تمثيل المنتفعين فى الإدارة والإشراف على المشروعات والأجهزة والوحدات التى تقوم على إدارة وتسيير المشروعات والخدمات العامة فى المحافظة فى المجالات وطبقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية . وتحدد اللائحة شروط اختيار ممثلى المنتفعين . ويعتبر ممثل المنتفعين مكلفا بخدمة عامة فى تطبيق أحكام قانون العقوبات ، ولا يجوز له التدخل فى سير العمل الادارى أو التنفيذى فى الجهات التى يمثل المنتفعين لديها كما لا يجوز له تقاضى أية مبالغ أو الحصول على أية مزايا من هذه الجهات أو معاملته أية معاملة خاصة فى أى تعامل معها ."}, {"number": "18", "chapter": "الفصل الأول", "text": "يبدى المجلس الشعبى المحلى للمحافظة رأيه فى الموضوعات التى يرى المحافظ أو الوزراء المختصون استشارته فيها . وعلى المحافظ أن يعرض على رئيس مجلس الوزراء رغبات المجلس الشعبى المحلى المتعلقة بالحاجات العامة للمحافظة والتى لا يمكن تنفيذها محليا. مستبدلة بالقانون رقم 50 لسنة 1981 . الفرع الثالث الأسئلة وطلبات الاحاطة"}, {"number": "19", "chapter": "الفصل الأول", "text": "لكل عضو من أعضاء المجلس الشعبى المحلى للمحافظة أن يوجه للمحافظ ،أو نائبى المحافظ ولكل من رؤساء المصالح ورؤساء الهيئات العامة فى نطاق المحافظة أسئلة فى الشئون التى تدخل فى اختصاصاتهم ويجب أن يكون السؤال فى أمر من الأمور المحلية وألا يكون متعلقا بمصلحة خاصة بمقدمه أو تكون له صفة شخصية . وعلى المحافظ أو غيره ممن توجه إليهم أسئلة الأعضاء الإجابة عليها بجلسة المجلس الشعبى المحلى إلا إذا رأى المجلس الاكتفاء برد مكتوب عنها. ويجوز للمحافظ أن ينيب فى الرد على الأسئلة الموجهة إليه رؤساء المصالح والهيئات العامة . وتنظم اللائحة الداخلية للمجلس الشعبى إجراءات وأوضاع تقديم الأسئلة والرد عليها . مستبدلة بالقانون رقم 50 لسنة 1981"}, {"number": "20", "chapter": "الفصل الأول", "text": "لكل عضو من أعضاء المجلس الشعبى المحلى للمحافظة أن يطلب احاطه المحافظ أو غيره من نائبى المحافظ أو من رؤساء المصالح ورؤساء الهيئات العامة فى المحافظة علما بأمر له أهمية عامة وعاجلة فى الشئون الداخلة فى اختصاصاتهم . وعلى مقدم طلب الإحالة أن يحدد الأمور التى يتضمنها ويبين صفتها العامة والعاجلة وتنظم اللائحة الداخلية للمجلس إجراءات وأوضاع تقديم طلبات الإحالة والإجابة عنها . مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "20 مكرر", "chapter": "الفصل الأول", "text": "ملغاة بالقانون رقم 145 لسنة 1988."}, {"number": "20 مكرر", "chapter": "الفصل الأول", "text": "1 ملغاة بالقانون رقم 145 لسنة 1988. الفرع الرابع نظام سير العمل بالمجالس الشعبية المحلية للمحافظات"}, {"number": "21", "chapter": "الفصل الأول", "text": "يعقد مقر للمجلس الشعبى المحلى ولجانه بعاصمة المحافظة ويلحق بالمجلس العدد الكافى من العاملين اللازمين لحسن سير العمل بالمجلس ويكون لرئيس المجلس الإشراف عليهم وله بالنسبة لهم سلطة الوزير . كما تدرج بموازنة المحافظة سنويا الاعتمادات اللازمة لمواجهة نفقات المجلس الشعبى المحلى وتوضع هذه الاعتمادات تحت تصرف رئيس المجلس الشعبى المحلى باعتباره الآمر بالصرف ."}, {"number": "22", "chapter": "الفصل الأول", "text": "دور الانعقاد العادى للمجلس الشعبى المحلى للمحافظات عشرة أشهر على الأقل . ويجتمع المجلس فى المقر المعد له بعاصمة المحافظة اجتماعا عاديا مرة على الأقل كل شهر بدعوة من رئيسه فى الموعد الذى يحدده ويجوز دعوة المجلس لاجتماع غير عادى فى حالة الضرورة بناء على طلب رئيس المجلس أو المحافظ أو ثلث أعضاء المجلس . وفيما عدا ما ورد بشأنه نص خاص لا يكون اجتماع المجلس صحيحا إلا بحضور أغلبية أعضائه وتصدر قرارات المجلس فى المسائل الداخلة فى اختصاصاته بالأغلبية المطلقة للحاضرين وعند تساوى الأصوات يرجح الجانب الذى منه الرئيس ."}, {"number": "23", "chapter": "الفصل الأول", "text": "يحضر المحافظ أو من يحل محله عند الضرورة جلسات المجلس الشعبى المحلى ، كما يحضرها رؤساء المصالح والوحدات المحلية ورؤساء الهيئات العامة ممن تتصل اختصاصاتهم بالمسائل المعروضة على المجلس . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "24", "chapter": "الفصل الأول", "text": "لأعضاء مجلسى الشعب والشورى فى المحافظة حضور جلسات المجلس الشعبى المحلى للمحافظة والمشاركة فى مناقشتها ، ويكون لهم حق تقديم الاقتراحات والأسئلة وطلبات الإحاطة دون أن يكون لهم صوت معدود فى اتخاذ القرارات . مستبدلة بالقانون رقم 145 لسنة 1988"}, {"number": "25", "chapter": "الفصل الثانى", "text": "يكون لكل محافظة محافظ يصدر بتعيينه وإعفائه من منصبه قرار من رئيس الجمهورية . ولا يجوز للمحافظ أن يكون عضوا بمجلس الشعب أو مجلس الشورى أو بالمجالس الشعبية المحلية . ويعامل المحافظ معاملة الوزير من حيث المرتب والمعاش . ويقسم المحافظ أمام رئيس الجمهورية قبل مباشرته أعمال وظيفته اليمين التالية : \" أقسم بالله العظيم أن أحافظ مخلصا على النظام الجمهورى وأن أرعى مصالح الشعب وسلامة الوطن وأن احترم الدستور والقانون وأن أؤدى عملى بالذمة والصدق \" . ويعتبر المحافظون مستقيلين بحكم القانون بانتهاء رئاسة رئيس الجمهورية ولا يترتب على ذلك سقوط حقهم فى المعاش أو المكافأة ويستمرون فى مباشرة أعمال وظائفهم الى أن يعين رئيس الجمهورية الجديد المحافظين الجدد . مستبدلة بالقانون رقم 26 لسنة 1982."}, {"number": "26", "chapter": "الفصل الثانى", "text": "يعتبر المحافظ ممثلا للسلطة التنفيذية بالمحافظة ويشرف على تنفيذ السياسة العامة للدولة وعلى مرافق الخدمات والإنتاج فى نطاق المحافظة . ويكون مسئولا عن كفالة الأمن الغذائى ورفع كفاءة الإنتاج الزراعى والصناعى والنهوض به وله أن يتخذ كافة الإجراءات الكفيلة بتحقيق ذلك فى حدود القوانين واللوائح . كما يكون مسئولا عن الأمن والأخلاق والقيم العامة بالمحافظة يعاونه فى ذلك مدير الأمن فى إطار السياسة التى يضعها وزير الداخلية وعلى مدير الأمن أن يبحث مع المحافظ الخطط الخاصة بالحفاظ على أمن المحافظة لاعتمادها ، ويلتزم مدير الأمن بإخطاره فورا بالحوادث ذات الأهمية الخاصة لاتخاذ التدابير اللازمة فى هذا الشأن بالاتفاق بينهما . وللمحافظ أن يتخذ جميع الإجراءات الكفيلة بحماية أملاك الدولة العامة والخاصة وإزالة ما يقع عليها من تعديات بالطريق الادارى . مستبدلة بالقانون رقم 145 لسنة 1988."}, {"number": "27", "chapter": "الفصل الثانى", "text": "يتولى المحافظ بالنسبة إلى جميع المرافق العامة التى تدخل فى اختصاص وحدات الإدارة المحلية وفقا لأحكام هذا القانون جميع السلطات والاختصاصات التنفيذية المقررة للوزراء بمقتضى القوانين واللوائح ويكون المحافظ فى دائرة اختصاصه رئيسا لجميع الأجهزة والمرافق المحلية . وتكون للمحافظ السلطة المقررة للوزير بالنسبة للقرارات الصادرة من مجالس إدارات الهيئات العامة التى تتولى مرافق عامة للخدمات فى نطاق المحافظة . ويتولى الإشراف على المرافق القومية بدائرة المحافظة وكذلك جميع فروع الوزارات التى لم تنقل اختصاصاتها إلى الوحدات المحلية فيما عدا الهيئات القضائية والجهات المعاونة لها وذلك بإبداء الملاحظات واقتراح الحلول اللازمة فى شأن الإنتاج وحسن الأداء ، كما يتولى بالنسبة لجميع المرافق اتخاذ التدابير الملائمة لحماية أمنها . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "27 مكرر", "chapter": "الفصل الثانى", "text": "يعمل المحافظ على دعم التعاون بين أجهزة المحافظة والجامعات والمعاهد العليا التى تقع بدائرة المحافظة لخدمة البيئة والنهوض بالمجتمع المحلى ويتم إنشاء الكليات والمعاهد العليا بالاتفاق بين المحافظ ومجلس الجامعة المختص والمجلس الأعلى للجامعات والوزير المختص بالتعليم العالى ، على أن يكون المحافظ ورئيس الجامعة مسئولين عن الأمن بالجامعات وذلك على النحو الذى تبينه اللائحة التنفيذية مضافة بالقانون رقم 50 لسنة 1981."}, {"number": "27 مكرر", "chapter": "الفصل الثانى", "text": "1 يكون المحافظ رئيسا لجميع العاملين المدنيين فى نطاق المحافظة فى الجهات التى نقلت اختصاصاتها إلى الوحدات المحلية ويمارس بالنسبة لهم جميع اختصاصات الوزير. ويختص المحافظ بالنسبة للعاملين المدنيين بفروع الوزارات والجهات التى لم ينقل اختصاصها إلى الوحدات المحلية فيما عدا الهيئات القضائية والجهات المعاونة لها بما يأتى : (أ) اقتراح نقل أى عامل من المحافظة إذا تبين أن وجوده فيها لا يتلاءم مع المصلحة العامة . (ب) إبداء الرأى فى ترقية ونقل العاملين بالمحافظة قبل صدور القرار من السلطة المختصة. (ج) الإحالة إلى التحقيق وتوقيع الجزاءات التأديبية فى الحدود المقررة للوزارة . (د) طلب التحقيق مع العاملين التابعين للهيئات العامة التى تمارس نشاطها فى نطاق المحافظة واقتراح توقيع الجزاءات التأديبية عليهم من السلطة المختصة . ويجب أن يخطر المحافظ السلطة المختصة بما اتخذه من إجراء أو أصدر من قرارات فى الأحوال السابقة خلال سبعة أيام من تاريخ اتخاذه لها . ويجوز لكل وزير ممن لم تنقل اختصاصات وزارتهم إلى الوحدات المحلية أن يفوض المحافظ فى بعض اختصاصاته . مضافة بالقانون رقم 50 لسنة 1981."}, {"number": "28", "chapter": "الفصل الثانى", "text": "يجوز للمحافظ بعد موافقة المجلس الشعبى المحلى للمحافظة وفى حدود القواعد العامة التى يضعها مجلس الوزراء - أن يقرر قواعد التصرف فى الأراضى المعدة للبناء المملوكة للدولة ووحدات الإدارة المحلية فى المحافظة وقواعد التصرف فى الأراضى القابلة للاستزراع داخل الزمام والأراضى المتاخمة والممتدة لمسافة كيلو مترين التى تتولى المحافظة استصلاحها بعد أخذ رأى وزارة استصلاح الاراضى ، على أن تعطى الأولوية فى هذا التصرف أبناء المحافظة المقيمين فيها العاملين فى دائرتها ، ويجوز أن تنظم هذه القواعد الحالات التى يتم فيها التصرف فى هذه الأراضى دون مقابل لأغراض التعمير والإسكان واستصلاح الأراضى وتهيئتها للزراعة. وفيما يتعلق بالأراضى الواقعة خارج الزمام فيكون استصلاحها وفق خطة قومية تتولى تنفيذها وزارة استصلاح الأراضى والجهات التى تحددها بالتنسيق مع المحافظة المختصة ويكون التصرف فى هذه الأراضى وتحديد نصيب المحافظة فى قيمتها طبقا للأحكام والقواعد والإجراءات المنصوص عليها فى القوانين واللوائح المعمول بها فى هذا الشأن . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "29", "chapter": "الفصل الثانى", "text": "يكون للمحافظ اختصاصات الوزير المختص وكذلك اختصاصات وزير المالية المنصوص عليها فى اللوائح وذلك فى المسائل المالية والإدارية بالنسبة للمرافق التى نقلت إلى الوحدات المحلية ولأجهزتها وموازناتها ، وذلك بما لا يتعارض مع التأشيرات العامة المرافقة لقانون ربط الموازنة العامة للدولة ."}, {"number": "29 مكرر", "chapter": "الفصل الثانى", "text": "يكون المحافظ مسئولا أمام رئيس مجلس الوزراء عن مباشرته لاختصاصاته المنصوص عليها فى هذا القانون ، ويلتزم بتقديم تقارير دوريه إلى الوزير المختص بالإدارة المحلية عن نتائج الأعمال فى مختلف الأنشطة التى تزاولها المحافظة وأية موضوعات تحتاج إلى تنسيق مع المحافظات الأخرى أو الوزارات المعنية ، على أن يعرض الوزير المختص بالإدارة المحلية على رئيس مجلس الوزراء تقريرا دوريا عن نتائج الأعمال فى المحافظات المختلفة وذلك بعد دراسة التقارير الدورية التى تقدم له من المحافظين ، ولرئيس مجلس الوزراء أن يعقد اجتماعات دوريه مشتركة بين الوزراء والمحافظين لمناقشة وسائل دعم التعاون والتنسيق بين الوزارات والمحافظات تبادل الرأى فى أسلوب تذليل ما قد يعترض نشاط وحدات الإدارة المحلية من عقبات . مضافة بالقانون رقم 50 لسنة 1981."}, {"number": "30", "chapter": "الفصل الثانى", "text": "يجوز أن يكون للمحافظ نائب أو أكثر للمحافظ يصدر بتعيينه وإعفاءه من منصبه قرار من رئيس الجهورية. ولا يجوز لنائب المحافظ أن يكون عضوا بمجلس الشعب أو مجلس الشورى أو بالمجالس الشعبية المحلية . ويعامل نائب المحافظ معامله نائب الوزير من حيث المرتب والمعاش . ويقسم نائب المحافظ أمام رئيس الجمهورية قبل مباشرته أعمال وظيفته اليمين المنصوص عليها فى المادة 25 . ويباشر نائب المحافظ أعماله تحت أشراف المحافظ وتوجيهه . ويعتبر نواب المحافظين مستقيلين بحكم القانون بانتهاء رئاسة الجمهورية . ولا يترتب على ذلك سقوط حقهم فى المعاش أو المكافأة ويستمرون فى مباشرة أعمال وظائفهم إلى أن يعين رئيس الجمهورية الجديد النواب الجدد للمحافظين . ويكون لكل محافظة سكرتير عام له سلطات واختصاصات وكيل الوزارة فى المسائل المالية والإدارية المنصوص عليها فى القوانين واللوائح بالنسبة لديوان عام المحافظة ، كما يكون لكل محافظة سكرتير عام مساعد يعاون السكرتير العام ، ويحل محله عند غيابه ، ولا يجوز لأى من شاغلى المناصب السابقة أن يكون عضوا بالمجالس الشعبية المحلية . معدلة بالقانون رقم 26 لسنة 1982"}, {"number": "31", "chapter": "الفصل الثانى", "text": "للمحافظ أن يفوض بعض سلطاته واختصاصاته إلى نوابه أو إلى سكرتير عام المحافظة أو السكرتير العام المساعد أو إلى رؤساء المصالح أو رؤساء الوحدات الأخرى."}, {"number": "32", "chapter": "الفصل الثانى", "text": "يشكل بكل محافظة مجلس تنفيذى برئاسة المحافظ وعضوية : (1) نواب المحافظ . (2) رؤساء المراكز والمدن والأحياء ورؤساء المصالح والأجهزة والهيئات العامة فى نطاق المحافظة الذين تحددهم اللائحة التنفيذية . (3) سكرتير عام المحافظة ويكون أمينا للمجلس . ويجتمع هذا المجلس بدعوة من المحافظ مرة على الأقل كل شهر فى المكان الذى يحدده ."}, {"number": "33", "chapter": "الفصل الثانى", "text": "يتولى المجلس التنفيذى للمحافظة الاختصاصات الآتية : (ا) متابعة الأعمال التى تتولاها الأجهزة التنفيذية للمحافظة وتقييم مستوى الأداء وحسن إنجاز المشروعات والخدمات على مستوى المحافظة . (ب) إعداد مشروع موازنة المحافظة واقتراح توزيع الاعتمادات المخصصة للاستثمارات - بعد اعتمادها - على الوحدات المحلية . (ج) معاونة المحافظ فى وضع الخطط الإدارية والمالية اللازمة لشئون المحافظة ولوضع القرارات والتوصيات الصادرة من المجلس الشعبى المحلى موضع التنفيذ . (د) وضع القواعد التى تكفل حسن سير العمل بالأجهزة الإدارية التنفيذية بالمحافظة . (هـ) وضع القواعد العامة لإدارة واستثمار أراضى المحافظة وممتلكاتها والتصرف فيها . (و) وضع القواعد الخاصة بمشروعات الإسكان والتخطيط العمرانى . (ز) دراسة وإبداء الرأى فى الموضوعات التى ستعرض على المجلس الشعبى المحلى للمحافظة من النواحى الفنية والإدارية والقانونية . (ح) دراسة وإبداء الرأى فى الموضوعات الاستثمارية التى تتولاها المحافظة. (ط) دراسة وبحث ما يحيله إليه المحافظ أو المجلس الشعبى المحلى من الموضوعات ."}, {"number": "33 مكرر", "chapter": "الفصل الثانى", "text": "يجوز للمحافظ أن يدعوا أعضاء مجلسى الشعب والشورى بالمحافظة لاجتماع يشترك فيه أعضاء المجلس التنفيذى أو بعضهم وذلك لمناقشة أسلوب تحقيق التنمية الاقتصادية والاجتماعية بالمحافظة وتنفيذ الخطط والبرامج المتعلقة بهذا الشأن ولتبادل الرأى فيما يطرح من موضوعات ، ولنصف أعضاء مجلسى الشعب والشورى بالمحافظة الحق فى الدعوة إلى عقد هذا الاجتماع. مضافة بالقانون رقم 50 لسنة 1981."}, {"number": "34", "chapter": "الفصل الثانى", "text": "يحل أقدم نواب المحافظ ، وفقا لترتيب أقدميتهم ، محل المحافظ فى حالة غيابه وفى حالة غيابهم يحل مدير الأمن ثم أقدم رؤساء المصالح محل المحافظ ويباشر من يحل محل المحافظ جميع اختصاصاته ."}, {"number": "35", "chapter": "الفصل الثالث", "text": "تشمل موارد المحافظات ما يأتى : أولا : الموارد المشتركة مع سائر المحافظات وتتضمن ما يأتى : (أ) الغى . (ب) نصيب المحافظة فى الضريبة الإضافية على ضريبة القيم المنقولة وضريبة الأرباح التجارية والصناعية . وتختص المحافظة بنصف حصيلة هذه الضريبة ، ويودع النصف الآخر فى رصيد الموارد المشتركة . وإذا اختلف المركز الرئيسى لإحدى المنشآت عن مركز نشاطها الفعلى ، اختص المجلس الشعبى المحلى للمحافظة الكائن فى دائرته مركز النشاط الفعلى بفرض الضريبة الإضافية وتحتفظ هذه المحافظة بنصف حصيلة هذه الضريبة ويودع النصف الآخر فى رصيد الموارد المشتركة . ويصدر قرار من الوزير المختص بالإدارة المحلية بتوزيع حصيلة الموارد المشتركة على المحافظات المختلفة . ثانيا : الموارد الخاصة بالمحافظة ، وتتضمن ما يأتى : (أ) ربع حصيلة الضريبة الأصلية المقررة على الأطيان فى المحافظة وكذلك ربع حصيلة الضريبة الإضافية على ضريبة الأطيان فى المحافظة. (ب) ضرائب ورسوم السيارات والموتوسيكلات والعربات والدراجات ووسائل النقل المرخص بها من المحافظة . (ج) حصيلة استثمار أموال المحافظة وإيرادات المرافق التى تقوم بإدارتها . (د) الضرائب والرسوم الأخرى ذات الطابع المحلى التى تفرض لصالح المحافظة. (هـ) الإعانات الحكومية . (و) التبرعات والهبات والوصايا ، بشرط موافقة رئيس مجلس الوزراء على قبول ما يرد منها من هيئات أو أشخاص أجنبية. ويتولى المجلس الشعبى المحلى توزيع جزء من موارده المشار إليها فى البندين (أ ، ب) من (ثانيا) على الوحدات المحلية الداخلة فى نطاق اختصاصه بالنسبة التى يقررها بمراعاة ظروف كل وحدة واحتياجاتها . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "36", "chapter": "الفصل الثالث", "text": "ينشأ بكل محافظة حساب لأغراض استصلاح الأراضى على مستوى المحافظة ، تتكون موارده من حصيلة التصرف فى الأراضى الزراعية والمستصلحة المشار إليها فى المادة (28) من هذا القانون . كما ينشأ بالمحافظة حساب خاص لتمويل مشروعات الإسكان الاقتصادى على مستوى المحافظة ، تتكون موارده من : 1- حصيلة التصرف فى الأراضى المعدة للبناء المشار إليها فى المادة (28) من هذا القانون 2- حصيلة الاكتتاب فى سندات الإسكان المشار إليها فى المواد 4 ، 5 ، 6 من القانون رقم 107 لسنة 1976 بإنشاء صندوق مشروعات الإسكان الاقتصادى . 3- حصيلة مقابل الانتفاع الذى يؤدى فى حالات الإعفاء من قيود الارتفاع وفقا لأحكام قانون توجيه وتنظيم أعمال البناء وذلك على مستوى المحافظة 4- (ملغي بالقانون رقم 225 لسنة 1996) 5- المبالغ المختصة لأغراض الإسكان الاقتصادى فى المحافظات فى الاتفاقيات التى تعقدها الدولة 6- حصيلة إيجارات وأقساط تمليك المساكن المملوكة للمحافظة . 7- القروض . 8- الإعانات والتبرعات والهبات والوصايا. 9- حصيلة استثمار أموال هذا الحساب وقيمة إيجار المساكن التعويضية التى أقيمت بمدن القناة الثلاث وأقساط تمليك تلك المساكن . 10- حصيلة الغرامات التى يقضى بها طبقا للفقرة الأولى من المادة 21 من قانون توجيه وتنظيم أعمال البناء رقم 106 لسنة 1976 وذلك على مستوى المحافظة . وتعتبر موارد كل من الحسابين المشار إليهما من الموارد الذاتية للمحافظة ويرحل فائض كل من الحسابين فى نهاية كل سنة مالية إلى موازنة السنة التالية . وتنظم قواعد وإدارة كل من هذين الحسابين وقواعد الصرف منهما بقرار من مجلس الوزراء ، كما تحدد بقرار منه بالاتفاق مع وزير الاقتصاد التى تلتزم شركات التأمين بالاكتتاب بها فى سندات الإسكان ."}, {"number": "37", "chapter": "الفصل الثالث", "text": "ينشئ المجلس الشعبى المحلى للمحافظة حسابا للخدمات والتنمية المحلية تتكون موارده من : 1- الرسوم التى يفرضها المجلس الشعبى المحلى للمحافظة لصالح هذا الحساب . 2-أرباح المشروعات الإنتاجية التى يمولها الحساب المذكور . 3- التبرعات والهبات والوصايا التى يوافق المجلس الشعبى المحلى للمحافظة على تخصيصها لهذا الحساب . 4- 50% من الزيادة التى تتحقق فى الموارد المحلية للمحافظة عن الربط المقدر فى الموازنة ."}, {"number": "38", "chapter": "الفصل الثالث", "text": "تستخدم موارد حساب الخدمات والتنمية بالمحافظة وفقا لما يقرره المجلس الشعبى المحلى للمحافظة فى الأغراض الآتية : 1- تمويل المشروعات الإنتاجية والخدمات المحلية وفقا لخطة محلية يتم توزيعها واعتمادها فى إطار الخطة العامة للدولة . 2- استكمال المشروعات الواردة فى الخطة العامة التى لا تكفى الاعتمادات المالية المدرجة لها فى موازنة المحافظة لإتمامها وإنشاء المشروعات التى تقام بالجهود الذاتية . 3- رفع مستوى أداء الخدمات العامة المحلية . 4- الصرف على الخدمات العامة الحيوية العاجلة . ويصدر بتنظيم حساب الخدمات والتنمية قرار من المحافظ المختص . وتعامل أموال هذا الحساب معاملة الأموال العامة وبصفة خاصة فيما يتعلق بتطبيق قانون العقوبات وفيما يختص بالتحصيل والصرف والرقابة ، ولا يؤول فائض هذا الحساب إلى الخزانة العامة."}, {"number": "39", "chapter": "الفصل الأول", "text": "يشكل فى كل مركز مجلس شعبى محلى تمثل فيه المدينة عاصمة المركز باثنى عشر عضوا ، وتمثل المدينة التى تضم أكثر من قسم ادارى بأربعة عشر عضوا ، مع مراعاة تمثيل جميع الأقسام الإدارية المكونة للمدينة . وتمثل باقى الوحدات المحلية فى نطاق المركز بعشرة أعضاء عن كل وحدة . مستبدلة بالقانون رقم 84 لسنة 1996."}, {"number": "40", "chapter": "الفصل الأول", "text": "ينتخب المجلس الشعبى المحلى من بين أعضائه فى أول اجتماع لدور انعقاده العادى ولمدة هذا الدور رئيسا ووكيلا له على أن يكون أحدهما على الأقل من العمال أو الفلاحين . ويحل الوكيل محل رئيس المجلس عند غيابه وإذا غاب الرئيس والوكيل تكون الرئاسة لأكبر الأعضاء سنا . وإذا خلا مكان أحدهما انتخب المجلس من يحل محله إلى نهاية مدته ."}, {"number": "41", "chapter": "الفصل الأول", "text": "يتولى المجلس الشعبى المحلى للمركز فى نطاق السياسة العامة للمحافظة الإشراف والرقابة على أعمال المجالس المحلية للمدن والقرى الواقعة فى نطاق المركز والتصديق على قراراتها فى الحدود التى تقررها اللائحة التنفيذية . كما يتولى الرقابة على مختلف المرافق ذات الطابع المحلى التى تخدم أكثر من وحدة محلية فى نطاق المركز ويختص فى حدود القوانين واللوائح بما يأتى : 1- إقرار مشروع الخطة ومشروع الموازنة السنوية للمركز ومتابعة تنفيذها وإقرار مشروع الحساب الختامى . 2- تحديد وإقرار خطة المشاركة الشعبية بالجهود والإمكانيات الذاتية على مستوى المركز فى المشروعات المحلية ومتابعة تنفيذها . 3- اقتراح إنشاء مختلف المرافق التى تعود بالنفع العام على المركز . 4- تحديد وإقرار القواعد العامة لإدارة واستخدام ممتلكات المركز والتصرف فيها . 5- الموافقة على القواعد العامة لتنظيم تعامل أجهزة المركز مع الجماهير فى كافة المجالات . 6- الموافقة على القواعد اللازمة لتنظيم المرافق العامة المحلية بالمركز ورفع كفاءة العمل بها . 7- اقتراح خطط رفع الكفاية الإنتاجية ."}, {"number": "42", "chapter": "الفصل الأول", "text": "يجوز للمجلس الشعبى المحلى للمركز بعد موافقة المحافظ التصرف بالمجان فى مال من أموال المركز الثابتة أو المنقولة أو تأجيره بإيجار إسمى أو بأقل من أجر المثل بقصد تحقيق غرض ذى نفع عام وذلك إذا كان التصرف لإحدى الوزارات أو المصالح الحكومية أو الهيئات العامة أو شركات القطاع العام والجمعيات والمؤسسات الخاصة ذات النفع العام. وبمراعاة حكم الفقرة الثالثة من المادة (14) من هذا القانون ومع عدم الإخلال بأحكام القوانين الخاصة بتملك الأجانب للعقارات . لا يجوز للمجلس التصرف بالمجان أو التأجير بإيجار إسمى أو بأقل من أجر المثل لأحد الأشخاص الاعتبارية الخاصة أو لجهة أجنبية إلا لغرض ذى نفع عام وبموافقة الوزير المختص بالإدارة المحلية إذا كان ذلك فى حدود عشرين ألف جنيه فى السنة المالية الواحدة وبموافقة رئيس مجلس الوزراء فيما زاد على ذلك وبما لا يجاوز خمسين ألف جنيه ، وتجب موافقة مجلس الوزراء فيما يجاوز ذلك . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "43", "chapter": "الفصل الثانى", "text": "تشمل موارد المركز ما يأتى : 1- ما يخصصه المجلس الشعبى للمحافظة من موارده لصالح المركز. 2- حصيلة استثمار أموال المركز وإيرادات المرافق التى يديرها. 3- الإعانة الحكومية. 4- التبرعات والهبات والوصايا بشرط موافقة رئيس مجلس الوزراء على قبول ما يرد منها من هيئات أو أشخاص أجنبية . 5- القروض التى يعقدها المجلس. وينشىء المجلس الشعبى المحلى للمركز حسابا للخدمات والتنمية للمركز ويصدر بتنظيم هذا الحساب قرار من المحافظ وتعتبر أموال هذا الحساب أموالا عامة وبصفة خاصة فيما يتعلق بتطبيق قانون العقوبات وفيما يختص بالتحصيل والصرف والرقابة ولا يئول فائض هذا الحساب إلى الخزانة العامة. مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "44", "chapter": "الفصل الثالث", "text": "يكون لكل مركز رئيس هو رئيس المدينة عاصمة المركز يختاره رئيس مجلس الوزراء وتكون له سلطات وكيل الوزارة ورئيس المصلحة فى المسائل المالية والإدارية بالنسبة لأجهزة وموازنة المركز على النحو الذى تبينه اللائحة التنفيذية. ويجوز بقرار من المحافظ تعيين نائب لرئيس المركز ولرئيس المركز تفويضه فى بعض اختصاصاته ، ويحل نائب رئيس المركز محل رئيس المركز فى حالة غيابه ، وفى حالة غيابهما يحل مأمور المركز محل رئيس المركز ، ويباشر من يحل محل رئيس المركز جميع اختصاصاته. ويقسم رئيس المركز قبل مباشرته لأعماله اليمين المبينة بالمادة (25) من هذا القانون أمام المجلس الشعبى المحلى للمركز . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "45", "chapter": "الفصل الثالث", "text": "يشكل بكل مركز مجلس تنفيذى برئاسة رئيس وعضوية كل من : (1) مديرى إدارات الخدمات والإنتاج بالمركز الذين تحددهم اللائحة التنفيذية ورؤساء المدن والقرى الواقعة فى نطاقه . (2) سكرتير المركز ويكون أمينا للجنة . ويجتمع هذا المجلس بدعوة من رئيسه مرة على الأقل كل أسبوعين فى المكان الذى يحدده ."}, {"number": "46", "chapter": "الفصل الثالث", "text": "يختص المجلس التنفيذى بمعاونة رئيس المركز فى وضع الخطط الإدارية والمالية اللازمة لشئون المركز ولتنفيذ قرارات المجلس الشعبى المحلى للمركز كما يتولى القيام بما يأتى : (1) تزويد المدن والقرى بما يلزمها من أجهزة إدارية وفنية لمباشرة اختصاصاتها . (2) تقديم العون المالى للمدن والقرى التى تقصر مواردها الذاتية عن الوفاء باحتياجاتها وفى حدود ما يقرره المجلس الشعبى المحلى للمركز . (3) تنفيذ المشروعات التى تعجز المدن والقرى عن القيام بها. (4) دراسة واقتراح القيام بالمشروعات المشتركة التى تخدم أكثر من وحدة محلية بدائرة المركز . (5) التنسيق بين مشروعات المدن والقرى طبقا لتوجيهات وتقييم المجلس الشعبى المحلى للمركز . (6) متابعة الأعمال التى تتولاها الأجهزة التنفيذية للمركز وتقييم مستوى الأداء وحسن إنجاز المشروعات والخدمات على مستوى المركز . (7) إعداد مشروع موازنة المركز واقتراح توزيع الاعتمادات المخصصة للاستثمارات - بعد اعتمادها - على الوحدات المحلية المختلفة كما يتولى هذا المجلس مباشرة الاختصاصات المنصوص عليها فى المادة (33) فقرات د ، ز ، ح ، ط ، وذلك على مستوى المركز ."}, {"number": "47", "chapter": "الفصل الأول", "text": "يشكل فى كل مدينة مجلس شعبى محلى يمثل فيه كل قسم إدارى بأربعة عشر عضوا ، ويكون تمثيل المدينة ذات القسم الواحد بأربعة وعشرين عضوا . مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "48", "chapter": "الفصل الأول", "text": "ينتخب المجلس الشعبى المحلى من بين أعضائه فى أول اجتماع لدور انعقاده العادى ولمدة هذا الدور رئيسا ووكيلا له ، على أن يكون أحدهما على الأقل من العمال أو الفلاحين ويحل الوكيل محل رئيس المجلس عند غيابه وإذا غاب الرئيس والوكيل تكون الرئاسة لأكبر الأعضاء سنا . وإذا خلا مكان أحدهما انتخب المجلس من يحل محله إلى نهاية مدته ."}, {"number": "49", "chapter": "الفصل الأول", "text": "يتولى المجلس الشعبى المحلى للمدينة فى نطاق السياسة العامة للمركز الرقابة والإشراف على مجالس الأحياء والتنسيق بينها والرقابة على مختلف المرافق ذات الطابع المحلى فى نطاق المدينة ويختص فى حدود القوانين واللوائح بالمسائل المنصوص عليها فى البنود (1-7) من المادة (41) على مستوى المدينة"}, {"number": "50", "chapter": "الفصل الأول", "text": "يجوز للمجلس الشعبى المحلى للمدينة بعد موافقة المحافظ التصرف بالمجان فى مال من أموال المدينة الثابتة أو المنقولة أو تأجيره بإيجار إسمى أو بأقل من أجر المثل بقصد تحقيق غرض ذى نفع عام وذلك إذا كان لتصرف لإحدى الوزارات أو المصالح الحكومية أو الهيئات العامة أو شركات القطاع العام أو الجمعيات أو المؤسسات الخاصة ذات النفع العام. وبمراعاة حكم الفقرة الثالثة من المادة (14) من هذا القانون ومع عدم الإخلال بأحكام القوانين الخاصة بتملك الأجانب للعقارات لا يجوز للمجلس التصرف بالمجان أو التأجير بإيجار إسمى أو بأقل من أجر المثل لأحد الأشخاص الاعتبارية الخاصة أو لجهة أجنبية إلا لغرض ذى نفع عام وبموافقة الوزير المختص بالإدارة المحلية إذا كان ذلك فى حدود عشرين ألف جنيه فى السنة المالية الواحدة وبموافقة رئيس مجلس الوزراء فيما زاد على ذلك وبما لا يجاوز خمسين ألف جنيه ، ويجب موافقة مجلس الوزراء فيما يجاوز ذلك . مستبدلة بالقانون رقم 5 لسنة 1981"}, {"number": "51", "chapter": "الفصل الثانى", "text": "تشمل موارد المدينة ما يأتى : أولا: حصيلة الضريبة على العقارات المبنية الواقعة فى دائرة اختصاص المجلس والضرائب الإضافية المقررة عليها ما عدا الضرائب المخصصة حصيلتها طبقا للقانون لأغراض قومية . ثانيا : حصيلة ضريبتى الملاهى والمراهنات المفروضتين فى دائرة المدينة . ثالثا : 75 % من حصيلة الضريبة الأصلية المقررة على الأطيان الكائنة فى دائرة اختصاص المدينة و75 % من حصيلة الضريبة الإضافية المقررة على هذه الأطيان . رابعا : ما يخصصه المجلس الشعبى المحلى للمحافظة لصالح المدينة من الموارد المقررة للمحافظة . خامسا : حصيلة مقابل التحسين المفروض على العقارات التى انتفعت من أعمال المنفعة العامة بالفئات ووفقا للقواعد المقررة فى القانون الخاص بفرض مقابل تحسين على العقارات التى يطرأ عليها تحسين بسبب أعمال المنفعة العامة . سادسا : الرسوم التى يفرضها المجلس الشعبى المحلى للمدينة فى نطاقه فى حدود القوانين واللوائح على ما يأتى : 1- مستخرجات قيد المواليد والإجراءات الصحية . 2- رخص المحاجر والمناجم ورخص الصيد . 3- أعمال التنظيم والمجارى وأشغال الطرق والحدائق العامة. 4- المحال العمومية والأندية والمحال الصناعية والتجارية . 5- حيوانات الجر والكلاب والدواب وما ماثل ذلك . 6- المراكب التجارية ومراكب الصيد والنزهة ومعادى النيل والعائمات على اختلاف أنواعها . 7- ما يذبح فى المذابح العامة أو النقط المستعملة لذلك . 8- الأسواق المرخص فى إدارتها للأشخاص الخاصة . 9- استهلاك المياه والتيار الكهربائى والغاز فى حدود 1 % من قيمة الاستهلاك إذا لم يتول المجلس استغلال هذه المرافق بنفسه . 10- الانتفاع بالشواطئ والسواحل أو استغلالها . 11- الإيجارات التى يؤديها شاغلو العقارات المبنية الخاضعة لضريبة المبانى لغاية 4% على الأكثر من قيمتها الايجارية وذلك مع مراعاة أحكام القانون المنظم للعلاقة بين المؤجر والمستأجر وعلى ملاك العقارات المبنية أو المنتفعين بها تحصيل هذا الرسم من شاغليها وأداؤه فى مكاتب التحصيل فى المواعيد المحددة لأداء الضريبة على العقارات المبنية . سابعا : المقابل الذى يفرضه المجلس على الاستغلال أو الانتفاع بالمرافق العامة التابعة للمدينة أو التى تديرها الأجهزة التنفيذية فيها أو على استعمال واستغلال الأملاك العامة التى تديرها المدينة . ثامنا : حصيلة الحكومة فى نطاق المدينة من إيجار المبانى وأراضى البناء الفضاء الداخلة فى أملاكها الخاصة . تاسعا : إيرادات استثمار أموال المدينة والمرافق التى تتولاها وإيرادات الأسواق العامة الواقعة فى نطاقها . عاشرا : الإعانات الحكومية والتبرعات والوصايا والهبات بشرط موافقة رئيس مجلس الوزراء على قبول ما يرد منها من هيئات أو أشخاص أجنبية . حادى عشر : القروض التى يعقدها المجلس . مستبدل بالقانون رقم 50 لسنة 1981"}, {"number": "52", "chapter": "الفصل الثانى", "text": "يعفى من الرسوم المنصوص عليها فى البند (11 سادسا) من المادة السابقة : 1- العقارات التى تشغلها الوزارات والمصالح والهيئات العامة والمجالس الشعبية المحلية للوحدات المحلية والجمعيات المؤسسات الخاصة المشهرة طبقا للقانون. 2- العقارات المعفاة من الضريبة على العقارات المبنية . 3- العقارات المملوكة للدول الأجنبية بشرط المعاملة بالمثل ."}, {"number": "53", "chapter": "الفصل الثانى", "text": "لا يكون قرار المجلس فى شأن فرض الرسوم المنصوص عليها فى المادة 51 نافذا إلا بعد موافقة المجلس الشعبى المحلى للمركز والمحافظ . ويجوز للمحافظ أن يطلب من المجلس تقرير أو تعديل رسم محلى معين تمكينا له من مباشرة أعماله فيما يعود بالنفع المحلى كما يجوز له أن يطلب إلى المجلس إلغاء الرسم أو تعديله أو تقصير أجل سريانه إذا رأى أن بقاءه لا يتفق والسياسة الاقتصادية أو المالية للدولة . وإذا رفض المجلس فى الحالات المذكورة إجابة الطلب يعرض الأمر على المجلس الشعبى المحلى للمحافظة يقرر فيه ما يراه ، فاذا استمر الخلاف عرض الأمر على مجلس الوزراء ، ويكون قراره فى هذا الشأن نهائيا . مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "54", "chapter": "الفصل الثانى", "text": "ينشىء المجلس الشعبى المحلى للمدينة حسابا للخدمات والتنمية للمدينة ويصدر بتنظيم هذا الحساب قرار من المحافظ وتعتبر أموال هذا الحساب أموالا عامة وبصفة خاصة فيما يتعلق بتطبيق قانون العقوبات وفيما يختص بالتحصيل والصرف والرقابة ولا يؤول فائض هذا الحساب إلى الخزانة العامة ."}, {"number": "55", "chapter": "الفصل الثالث", "text": "يكون لكل مدينة رئيس له سلطات وكيل الوزارة ورئيس المصلحة فى المسائل المالية والإدارية بالنسبة لأجهزة وموازنة المدينة على النحو الذى تبينه اللائحة التنفيذية ويقسم اليمين المبينة بالمادة (25) أمام المجلس قبل مباشرته لأعماله."}, {"number": "56", "chapter": "الفصل الثالث", "text": "يشكل بكل مدينة مجلس تنفيذى برئاسة رئيس المدينة وعضوية كل من : 1- مديرى إدارات الخدمات والإنتاج بالمدينة الذين تحددهم اللائحة التنفيذية . 2- سكرتير المدينة ويكون أمينا للمجلس . ويجتمع هذا المجلس بدعوة من رئيسه مرة على الأقل كل أسبوعين فى المكان الذى يحدده ، وفى حالة غياب الرئيس يحل محله مأمور المركز ."}, {"number": "57", "chapter": "الفصل الثالث", "text": "يتولى المجلس التنفيذى معاونة رئيس المدينة فى وضع الخطط الإدارية والمالية اللازمة لشئون المدينة ولتنفيذ قرارات المجلس الشعبى المحلى للمدينة . كما يقوم بدراسة وبحث ما قد يحيله المجلس الشعبى المحلى أو رئيس المدينة من الموضوعات ويتولى المجلس بوجه خاص فى حدود القوانين واللوائح ما يأتى : 1- متابعة الأعمال التى تتولاها الأجهزة التنفيذية للمدينة وتقييم مستوى الأداء وحسن إنجاز المشروعات والخدمات على مستوى المدينة 2- أعداد مشروع موازنة المدينة واقتراح توزيع الاعتمادات المخصصة للاستثمارات - بعد اعتمادها - على مشروعات الأحياء المختلفة. 3- مراقبة تحصيل موارد المدينة أيا كان نوعها . 4- مساعدة المرافق والمنشآت والأجهزة المحلية . 5- الاشتراك مع وحدة محلية أخرى فى إنشاء أو إدارة أعمال أو مرافق لحساب الوحدتين وذلك بعد موافقة المجلس الشعبى والمحلى للمدينة . 6- وضع القواعد التى تكفل حسن سير العمل بالأجهزة الإدارية والتنفيذية بالمدينة . 7- مباشرة الاختصاصات المنصوص عليها فى المادة 33 فقرات ز ، ح ، ط . وذلك على مستوى المدينة ."}, {"number": "58", "chapter": "الفصل الأول", "text": "يجوز تقسيم المحافظة ذات المدينة الواحدة أو المدن الكبرى إلى أحياء ."}, {"number": "59", "chapter": "الفصل الأول", "text": "يشكل فى كل حى مجلس شعبى محلى يمثل فيه كل قسم ادارى بأثنى عشر عضوا ويشكل المجلس الشعبى المحلى للحى الذى يضم قسما اداريا واحدا من ثمانية عشر عضوا . مستبدلة بالقانون رقم 84 لسنة 1996."}, {"number": "60", "chapter": "الفصل الأول", "text": "ينتخب المجلس الشعبى المحلى من بين أعضائه فى أول اجتماع لدور انعقاده العادى ولمدة هذا الدور رئيسا ووكيلا له على أن يكون أحدهما على الأقل من العمال أو الفلاحين . ويحل الوكيل محل الرئيس عند غيابه وإذا غاب الرئيس والوكيل تكون الرئاسة لأكبر الأعضاء سنا . وإذا خلا مكان أحدهما انتخب المجلس من يحل محله الى نهاية مدته ."}, {"number": "61", "chapter": "الفصل الأول", "text": "يتولى المجلس الشعبى المحلى للحى فى نطاق السياسة العامة للمدينة الرقابة والإشراف على مختلف المرافق ذات الطابع المحلى فى نطاق الحى ويختص فى حدود القوانين واللوائح بالمسائل المنصوص عليها فى البنود من (1- 7) من المادة (41) على مستوى الحى ."}, {"number": "62", "chapter": "الفصل الأول", "text": "يتولى كل حى من أحياء المدينة فى نطاقه تحصيل الموارد المنصوص عليها فى المادة (51 ) لحساب المدينة وذلك فيما عدا الموارد التى يقرر المجلس الشعبى المحلى للمدينة تحصيلها مباشرة بواسطة أجهزة المدينة الأخرى أو بواسطة الأجهزة الحكومية المختصة . ويقوم المجلس الشعبى المحلى للمدينة بتقرير الاعتمادات التى تغطى مصروفات كل حى ."}, {"number": "63", "chapter": "الفصل الثانى", "text": "يكون لكل حى رئيس وتكون له سلطات وكيل الوزارة ورئيس المصلحة فى المسائل المالية والإدارية ، ويقسم رئيس الحى قبل مباشرته لأعماله اليمين المبينة بالمادة (25) أمام المجلس الشعبى المحلى للحى ."}, {"number": "64", "chapter": "الفصل الثانى", "text": "يشكل بكل حى مجلس تنفيذى برئاسة رئيس الحى وعضوية كل : 1- رؤساء الأجهزة التنفيذية فى نطاق الحى الذين تحددهم اللائحة التنفيذية . 2- سكرتير الحى ويكون أمينا للجنة . ويجتمع هذا المجلس بدعوة من رئيسه مرة على الأقل كل أسبوعين فى المكان الذى يحدده ، وفى حالة غياب الرئيس يحل محله أقدم رؤساء الأجهزة التنفيذية ."}, {"number": "65", "chapter": "الفصل الثانى", "text": "يتولى المجلس التنفيذى معاونة رئيس الحى فى وضع الخطط الإدارية والمالية اللازمة لشئون الحى . كما يقوم بدراسة وبحث ما قد يحيله اليه المجلس المحلى أو رئيس الحى من الموضوعات ويتولى المجلس بوجه خاص فى حدود القوانين واللوائح ما يأتى : 1- مراقبة تحصيل الموارد المنصوص عليها فى المادة 51 2- وضع القواعد التى تكفل حسن سير العمل بالأجهزة الإدارية والتنفيذية بالحى . 3- مباشرة الاختصاصات المنصوص عليها فى المادة 34 فقرات ز ، ح ، ط ، وذلك على مستوى الحى . 4- متابعة الأعمال التى تتولاها الأجهزة التنفيذية للحى وتقييم مستوى الأداء وحسن إنجاز المشروعات والخدمات على مستوى الحى . 5- اقتراح الاعتمادات التى تخصص للاستثمارات على مستوى الحى ."}, {"number": "66", "chapter": "الفصل الأول", "text": "يشكل فى كل قرية تمثل وحدة محلية مجلس شعبى محلى من أربعة وعشرين عضوا . فاذا كان نطاق الوحدة المحلية للقرية يشمل مجموعة من القرى المتجاورة تمثل القرية التى فيها مقر المجلس بعضوين على الأقل ، وباقى القرى بعضو واحد لكل منها على الأقل ولا يجوز فى جميع الأحوال أن يزيد عدد أعضاء المجلس عن أربعة وعشرين عضوا إلا بالعدد الذى يقتضيه تمثيل كل قرية من القرى الداخلة فى نطاق الوحدة المحلية للقرية. مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "67", "chapter": "الفصل الأول", "text": "ينتخب المجلس الشعبى المحلى من بين أعضائه فى أول اجتماع لدور انعقاده العادى ولمدة هذا الدور رئيسا ووكيلا له على أن يكون أحدهما على الأقل من العمال أو الفلاحين . ويحل الوكيل محل رئيس المجلس عند غيابه ، وإذا غاب الرئيس والوكيل تكون الرئاسة لأكبر الأعضاء سنا ، وإذا خلا مكان أحدهما انتخب المجلس من يحل محله الى نهاية مدته ."}, {"number": "68", "chapter": "الفصل الأول", "text": "يتولى المجلس الشعبى المحلى للقرية فى نطاق السياسة العامة للمركز الرقابة على مختلف المرافق ذات الطابع المحلى فى نطاقه ويختص فى حدود القوانين واللوائح بما يأتى : 1- اقتراح خطة تنمية القرية اقتصاديا واجتماعيا وعمرانيا . 2- اقتراح مشروع الموازنة ، وإقرار مشروع الحساب الختامى . 3- اقتراح وسائل المشاركة الشعبية بالجهود والإمكانيات الذاتية فى نطاق القرية لرفع مستواها . 4- العمل على نشر الوعى الزراعى بما يحقق تحسين وتنويع الإنتاج الزراعى. 5- اقتراح إنشاء مختلف المرافق العامة بالقرية . 6 - العمل على محو الأمية وتنظيم الأسرة ورعاية الشباب وتعميق القيم الدينية والخلقية ."}, {"number": "69", "chapter": "الفصل الثانى", "text": "تشمل موارد القرية ما يأتى : 1- 75 % من حصيلة الضريبة الأصلية المقررة على الأطيان الكائنة فى نطاق القرية . 75 % من حصيلة الضريبة الإضافية المقررة على هذه الأطيان . 2- حصيلة ضريبة الملاهى المفروضة فى نطاق القرية. 3- موارد أموال القرية والمرافق التى تقوم بإدارتها. 4- ما يخصصه المجلس الشعبى المحلى للمحافظة من موارد المحافظة لصالح القرية 5- الإعانات الحكومية . 6- التبرعات والهبات والوصايا بشرط موافقة رئيس مجلس الوزراء على قبول ما يرد منها من هيئات أو أشخاص أجنبية. 7- القروض التى يعقدها المجلس . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "70", "chapter": "الفصل الثانى", "text": "ينشأ بكل قرية حساب خاص للخدمات والتنمية المحلية بها تتكون موارده من : 1- 75% من حصيلة الرسوم المفروضة طبقا لأحكام المادة (37) المحصلة فى نطاق القرية . 2- أموال المشروعات التى تدار على أساس رأس المال الدائر فى نطاق القرية. 3- مقابل تمليك المبانى فى نطاق القرية التى يتولى حساب الخدمات إنشاءها. 4- إيجارات المبانى السكنية والمرافق التى يتولى حساب الخدمات إنشاءها . 5- حصة الخدمات الاجتماعية من أرباح الجمعيات التعاونية الزراعية فى نطاق القرية . 6- الإعانات والتبرعات والهبات والوصايا التى يوافق على تخصيصها المجلس الشعبى المحلى للقرية ."}, {"number": "71", "chapter": "الفصل الثانى", "text": "تستخدم موارد حساب الخدمات والتنمية المحلية للقرية وفقا لما يقرره المجلس الشعبى المحلى للقرية فى الأغراض الآتية : 1- تمويل المشروعات الإنتاجية والخدمات المحلية وفقا لخطة محلية يتم وضعها واعتمادها من المجلس الشعبى المحلى للمحافظة فى إطار الخطة العامة للدولة . 2- استكمال المشروعات الواردة فى الخطة العامة التى لا تكفى الاعتمادات المقررة لها فى موازنة القرية لإتمامها وإنشاء المشروعات التى تقام بالجهود الذاتية وفقا للأولويات التى يقترحها المجلس الشعبى المحلى للقرية ويقرها مجلس شعبى محلى المحافظة . 3- رفع مستوى أداء الخدمات المحلية . ويصدر بتنظيم هذا الحساب قرار من المحافظ وتعامل أموال هذا الحساب معاملة الأموال العامة وبصفة خاصة فيما يتعلق بتطبيق قانون العقوبات وفيما يختص بالتحصيل والصرف والرقابة ولا يؤول فائض أموال هذا الحساب إلى الخزانة العامة ."}, {"number": "72", "chapter": "الفصل الثالث", "text": "يكون لكل قرية رئيس تكون له سلطات رئيس المصلحة فى المسائل المالية والإدارية بالنسبة لأجهزة وموازنة القرية ويقسم الرئيس قبل مباشرته لأعماله اليمين المبينة بالمادة 25 أمام المجلس الشعبى المحلى للقرية ."}, {"number": "73", "chapter": "الفصل الثالث", "text": "يشكل بكل قرية مجلس تنفيذى برئاسة رئيس القرية وعضوية كل من : 1- رؤساء الأجهزة التنفيذية بدائرة القرية الذين تحددهم اللائحة التنفيذية . 2- سكرتير القرية ويكون أمينا للجنة . ويجتمع هذا المجلس بدعوة من رئيسه مرة على الأقل كل أسبوعين فى المكان الذى يحدده وفى حالة غياب الرئيس يحل محله أقدم رؤساء الأجهزة التنفيذية بالقرية."}, {"number": "74", "chapter": "الفصل الثالث", "text": "يختص المجلس التنفيذى بمعاونة رئيس القرية فى وضع الخطط الإدارية والمالية اللازمة لشئون القرية ، ولتنفيذ قرارات وتوصيات المجلس الشعبى المحلى للقرية . كما يقوم بدراسة وبحث ما قد يحيله إليه المجلس الشعبى المحلى أو رئيس القرية من الموضوعات . ويتولى المجلس بوجه خاص فى حدود القوانين واللوائح ما يأتى: (1) مراقبة تحصيل موارد القرية أيا كان نوعها . (2) مساعدة المرافق والمنشآت والأجهزة المحلية . (3) وضع القواعد التى تكفل حسن سير العمل بالأجهزة الإدارية والتنفيذية بالقرية . (4) بحث احتياجات القرية من المرافق والخدمات والمشروعات اللازمة للتنمية الاقتصادية والاجتماعية والعمرانية للقرية ."}, {"number": "75", "chapter": "الفصل الأول", "text": "يشترط فيمن يرشح عضوا بالمجالس الشعبية المحلية ما يأتى : 1- أن يكون متمتعا بجنسية جمهورية مصر العربية . 2- أن يكون بالغا من العمر 25 سنة ميلادية كاملة على الأقل يوم الانتخاب. 3- أن يكون مقيدا فى جداول الانتخاب بالوحدة المحلية التى يرشح نفسه فى دائرتها وله محل إقامة فى نطاقها . 4- أن يجيد القراءة والكتابة . 5- أن يكون قد أدى الخدمة العسكرية الإلزامية أو أعفى من أدائها طبقا للقانون ، ولا يجوز لأفراد القوات المسلحة أو الشرطة أو أعضاء الهيئات القضائية الترشيح للعضوية بالمجالس الشعبية المحلية قبل تقديم استقالاتهم من وظائفهم . كما لا يجوز للعمد أو المشايخ أو رؤساء الوحدات المحلية أو مديرى المصالح أو رؤساء الأجهزة التنفيذية فى نطاق هذه الوحدات الترشيح لعضوية المجالس الشعبية المحلية للوحدات المحلية التى تدخل فى نطاق اختصاص وظائفهم قبل تقديم الاستقالة منها . ومع مراعاة القواعد المنظمة للاستقالة من القوات المسلحة والشرطة ، تعتبر الاستقالات المشار اليها فى الفقرتين السابقتين مقبولة بمجرد تقديمها . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "75 مكرر", "chapter": "الفصل الأول", "text": "يكون انتخاب أعضاء المجالس الشعبية المحلية على اختلاف مستوياتها عن طريق الانتخاب المباشر السرى العام . ويحدد لكل مرشح رمز يصدر به قرار من المحافظ . وعلى الناخب أن يبدى رأيه باختيار العدد المطلوب انتخابه ، وتعتبر باطلة جميع الأصوات المعلقة على شرط ، أو التى تعطى لأكثر من العدد المطلوب ، أو أقل من نصف هذا العدد ، أو إذا أثبت الناخب رأيه على بطاقة غير التى سلمها إليه رئيس اللجنة ، أو على ورقة عليها توقيع الناخب أو أى إشارة أو علامة أخرى تدل عليه . مضافة بالقانون رقم 50 لسنة 1981"}, {"number": "76", "chapter": "الفصل الأول", "text": "يقدم طلب الترشيح لعضوية المجلس الشعبى المحلى كتابة إلى المحافظة ، أو إحدى وحدات الإدارة المحلية الكائنة بنطاقها حسب الأحوال ، وذلك خلال المدة التى يحددها المحافظ ، على ألا تقل عن عشرة أيام من تاريخ فتح باب الترشيح . ويكون طلب الترشيح مصحوبا بإيصال بإيداع مبلغ مائه جنيه إذا كان الترشيح لعضوية المجلس الشعبى المحلى للمحافظة ، وخمسين جنيها إذا كان الترشيح لعضوية المجلس الشعبى المحلى للمركز أو المدينة أو الحى ، وخمسة وعشرين جنيها إذا كان الترشيح لعضوية المجلس الشعبى المحلى للقرية . ويجب أن يرفق بطلب الترشيح المستندات التى يحددها وزير الداخلية بقرار منه لإثبات توافر الشروط اللازمة للترشيح ، ويعفى المرشح الذى تجاوز عمره السن القانونية للتجنيد من تقديم شهادة أداء الخدمة العسكرية الإلزامية ، أو الإعفاء منها وتعتبر الأوراق والمستندات التى يقدمها المرشح أوراقا رسمية فى تطبيق أحكام قانون العقوبات . مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "77", "chapter": "الفصل الأول", "text": "تقيد طلبات الترشيح بحسب تواريخ ورودها فى سجل خاص وتعطى عنها إيصالات ويتبع فى شأن تقديمها الإجراءات التى يحددها المحافظ بقرار منه."}, {"number": "78", "chapter": "الفصل الأول", "text": "تشكل بقرار من المحافظ لجنة أو أكثر فى كل قسم ومركز ومدينة برئاسة أحد أعضاء الهيئات القضائية من درجة قاض أو وكيل نيابة أو ما يعادلها وعضوية ممثل لمديرية الأمن ، وممثل للمحافظة المختصة . وتتولى هذه اللجان فحص طلبات الترشيح لعضوية المجالس الشعبية المحلية وإعداد كشوف المرشحين ."}, {"number": "79", "chapter": "الفصل الأول", "text": "يعرض فى دائرة الوحدة المحلية كشف يتضمن أسماء المرشحين والصفة التى تثبت لكل منهم ، وذلك خلال الخمسة الأيام التالية لإقفال باب الترشيح ، وبالطريقة التى يعينها المحافظ بقرار منه . ولكل من تقدم للترشيح ولم يدرج أسمه فى الكشف المعد لذلك أن يطلب من اللجنة المشار إليها فى المادة السابقة ، وفى خلال المدة المنصوص عليها فى الفقرة السابقة ، إدراج اسمه . ويكون لكل مرشح الاعتراض على إدراج اسم أى من المرشحين ، أو على إثبات صفه غير صحيحة أمام اسمه أو أسم غيره من المرشحين فى الكشف المدرج فيه اسمه طوال مدة عرض الكشف المذكور . ويتم نشر كشوف المرشحين فى جميع وحدات الإدارة المحلية بلصقها على مقر المحافظة ومقر المجلس الشعبى المحلى المختص . مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "80", "chapter": "الفصل الأول", "text": "للمرشح الحصول على صورة رسمية معفاة من رسم الدمغة من جدول الناخبين فى الوحدة المحلية المرشح فيها مقابل رسم يحدد بقرار من المحافظ ، على ألا يتجاوز هذا الرسم جنيهين وتسلم إلى المرشح هذه الصورة الرسمية خلال عشرة أيام على الأكثر من تاريخ تقديمه الطلب ."}, {"number": "81", "chapter": "الفصل الأول", "text": "يلتزم المرشح بإتباع آداب الدعاية الانتخابية التى يصدر بها قرار من وزير الداخلية . ويجوز للمحافظ أن يزيل بالطريق الإدارى على نفقة المرشح كافة الملصقات ووسائل الدعاية الأخرى التى تتم على خلاف أحكام القرار المشار إليه ."}, {"number": "82", "chapter": "الفصل الأول", "text": "لا يجوز لأحد أن يرشح نفسه فى أكثر من وحده محليه وإلا اعتبر مرشحا فى الوحدة التى قيد ترشيحه فيها أولا . ألغيت الفقرة الثانية بالقانون رقم 84 لسنة 1996."}, {"number": "83", "chapter": "الفصل الأول", "text": "لكل مرشح أن يتنازل عن الترشيح بإعلان على يد محضر ، أو بطلب يقدمه إلى المحافظ المختص قبل يوم الانتخاب بسبعة أيام على الأقل ، وإذا تم التنازل بعد هذا الميعاد أثبت أمام اسم المرشح فى كشف المرشحين فى الوحدة المحلية إذا كان قد قيد فيه ، ويعلق التنازل يوم الانتخاب على باب مقر اللجنة الانتخابية واللجان الفرعية لها . مستبدلة بالقانون رقم 84 لسنة 1996."}, {"number": "84", "chapter": "الفصل الأول", "text": "للمحافظ فى الظروف الاستثنائية أن يقصر المواعيد المنصوص عليها فى المواد (76) و(79) و(83) من هذا القانون ."}, {"number": "85", "chapter": "الفصل الأول", "text": "مع مراعاة النسبة المقررة للعمال والفلاحين ، ينتخب عضو المجلس الشعبى المحلى بالأغلبية النسبية لعدد الأصوات الصحيحة التى أعطيت فى الانتخاب . وفى حالة تساوى أكثر من مرشح فى عدد الأصوات الصحيحة التى حصل عليها ويقتضى الأمر إعلان فوز مرشح واحد منهم لاستكمال العدد المطلوب انتخابه للمجلس الشعبى المحلى ، تجرى بينهم قرعة بمعرفة رئيس اللجنة العامة علانية ، ويعلن فوز من أسفرت عنه نتيجة القرعة . وإذا تقدم للترشيح عدد مساو للعدد المطلوب أعلن فوزهم بالتزكية . وإذا كان عدد المتقدمين للترشيح أقل من العدد المطلوب أعلن فوزهم ، على أن يتم استكمال باقى العدد المطلوب فى انتخابات تكميلية مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "86", "chapter": "الفصل الأول", "text": "مع مراعاة أحكام هذا القانون ولائحته التنفيذية، تجرى مديرية الأمن عملية الانتخاب لعضوية المجالس الشعبية المحلية طبقا للقواعد والإجراءات المنصوص عليها فى القانون رقم 73 لسنة 1956 بتنظيم مباشرة الحقوق السياسية ، ويشترك فى الانتخاب الناخبون المقيدة أسماؤهم فى جداول الانتخاب بالوحدة المحلية التى يجرى فيها . ويعلن المحافظ نتيجة الانتخاب ويدعو المجالس الشعبية المحلية المنتخبة إلى الاجتماع . وفى جميع الأحوال يجب أن تجتمع هذه المجالس خلال ثلاثين يوما من تاريخ إعلان نتيجة الانتخاب . مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "87", "chapter": "الفصل الأول", "text": "يؤول المبلغ الذى أودعه طالب الترشيح إلى حساب الخدمات والتنمية المحلية بالمحافظة للصرف منه على إزالة الملصقات وفقا للمادة 81 من هذا القانون ، وما زاد على ذلك يخصص لتمويل الأغراض التى من أجلها أنشئ هذا الحساب . مستبدلة بالقانون رقم 145 لسنة 1988 ."}, {"number": "88", "chapter": "الفصل الأول", "text": "يقسم عضو المجلس الشعبى المحلى أمام المجلس قبل مباشرة مهام العضوية اليمين الآتية : \"اقسم بالله العظيم أن أحافظ مخلصا على سلامة الوطن والنظام الجمهورى وأن أرعى مصالح الشعب وأن أحترم الدستور والقانون \"."}, {"number": "89", "chapter": "الفصل الأول", "text": "مدة المجلس الشعبى المحلى أربع سنوات ميلادية تبدأ من تاريخ أول اجتماع له وتنتهى مدة المجالس الشعبية المحلية الخاضعة لإشراف ورقابة مجالس شعبية محليه أخرى بانقضاء المدة القانونية لهذه المجالس . ويجوز لرئيس الجمهورية لأسباب يقدرها أن يقرر استمرار المجالس الشعبية المحلية لسنة خامسة . ويجرى الانتخاب لتجديد المجلس الشعبى المحلى خلال الستين يوما السابقة على انتهاء مدته . الفقرة الثانية من 89 ملغاة بالقانون رقم 178 لسنة 2005"}, {"number": "90", "chapter": "الفصل الأول", "text": "لا يتقاضى عضو المجلس الشعبى المحلى أية رواتب أو مكافآت مقابل عمله ، ويجوز منح أعضاء المجالس الشعبية المحلية والمجالس التنفيذية مقابل ما يتكبدونه من أعباء طبقا لما تحدده اللائحة التنفيذية ."}, {"number": "91", "chapter": "الفصل الأول", "text": "لا يسأل عضو المجلس الشعبى المحلى عما يبديه من آراء أثناء اجتماعات ومناقشات المجلس ولجانه . ويجب على السلطات المختصة إخطار المجلس الشعبى المحلى بما يتخذ من إجراءات جنائية ضد أعضاء المجلس خلال ثمان وأربعين ساعة على الأكثر من تاريخ اتخاذ هذه الإجراءات ، كما يتعين إخطاره قبل مباشرة أية إجراءات تأديبية ضدهم إذا كانوا من العاملين بالجهاز الادارى للدولة أو القطاع العام أو القطاع الخاص وفى جميع الحالات يبلغ المجلس بنتيجة التحقيق ويتعين أخذ موافقة المجلس الشعبى المحلى قبل تنفيذ نقل أحد أعضاء المجلس من وظيفته إلا إذا كان النقل بناء على طلبه ، وعلى الجهة التى يعمل بها عضو المجلس الشعبى المحلى أن تيسر له أداء واجبات العضوية وذلك طبقا للقواعد والأوضاع التى تحددها اللائحة التنفيذية . ولا يجوز تعيين أعضاء المجلس الشعبى المحلى فى وظائف وحدات الإدارة المحلية أو نقلهم إليها أثناء عضويتهم إلا بموافقة ثلثى أعضاء المجلس الشعبى المحلى المختص وأغلبية أعضاء المجلس الشعبى المحلى للمحافظة. مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "92", "chapter": "الفصل الأول", "text": "يحظر التعاقد بالذات أو بالواسطة بين الوحدة المحلية وأى عضو فى مجلسها الشعبى المحلى ومع ذلك يجوز عند الضرورة وفى حالة وجود مصلحة محققة للوحدة المحلية أن يبرم العقد مع العضو بعد موافقة أغلبية أعضاء المجلس الشعبى المحلى والمحافظ المختص ."}, {"number": "93", "chapter": "الفصل الأول", "text": "يحظر على عضو المجلس الشعبى المحلى أن يحضر جلسات المجلس أو لجانه إذا كانت له أو لأحد أقربائه أو أصهاره لغاية الدرجة الرابعة بالذات أو بالواسطة مصلحة شخصية فى المسألة المعروضة أو إذا كان وصيا أو قيما أو وكيلا عمن له فيها مثل هذه المصلحة ."}, {"number": "94", "chapter": "الفصل الأول", "text": "تقدم الاستقالة من عضوية المجلس الشعبى المحلى الى رئيسه ويجب عليه عرضها على المجلس فى أول جلسة تالية لتقديمها وتعتبر الاستقالة مقبولة بموافقة المجلس عليها وفى هذه الحالة يقرر المجلس خلو المحل ويخطر رئيس المجلس المحافظ بخلو المحل ."}, {"number": "95", "chapter": "الفصل الأول", "text": "إذا غاب العضو عن جلسات المجلس الشعبى المحلى أو لجانه أكثر من ثلاث مرات متوالية أو عن ربع عدد جلسات المجلس فى الدور الواحد وذلك بدون عذر مقبول أصدر المجلس قرارا بدعوة العضو لسماع أقواله فى جلسة تحدد بعد خمسة عشر يوما على الأقل من تاريخ إخطار العضو بموعدها . ويصدر المجلس قرارا باعتبار العضو مستقيلا بأغلبية ثلثى أعضائه وذلك إذا لم يقتنع بما يبديه العضو من دفاع عن نفسه أو إذا غاب العضو عن الحضور فى الجلسة المشار إليها ."}, {"number": "96", "chapter": "الفصل الأول", "text": "تسقط عضوية المجلس الشعبى المحلى عمن تزول عنه صفة العامل أو الفلاح التى قام عليها انتخابه فى المجلس أو بفقد شرط من الشروط اللازمة للترشيح ويجب إسقاط العضوية عمن تثبت مخالفته لأحكام المادة 92 أو من يفقد الثقة أو الاعتبار كما يجوز إسقاط العضوية فى حالة إخلال العضو بواجبات العضوية الأخرى أو بمقتضياته. ويجب فى جميع الأحوال السابقة صدور قرار من المجلس بإعلان سقوط العضوية أو بإسقاطها وذلك بعد دعوة العضو لسماع أقواله فى المواعيد وطبقا للقواعد وبالأغلبية المنصوص عليها فى المادة السابقة 0 مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "97", "chapter": "الفصل الأول", "text": "مع مراعاة النسبة المقررة للعمال والفلاحين إذا خلا مكان أحد أعضاء المجلس الشعبى المحلى قبل انتهاء مدة عضويته حل محله الحاصل على عدد الأصوات الصحيحة التالية له مباشرة ، فان لم يوجد يجرى انتخاب تكميلى بالطريقة ذاتها ، وذلك مع مراعاة حكم المادة 66 من ذات القانون . وتجرى الانتخابات التكميلية لاستكمال تشكيل المجالس الشعبية المحلية ، أو لشغل المقاعد الخالية فيما بين أدوار الانعقاد العادية للمجالس الشعبية المحلية . وفى جميع الأحوال تكون مدة العضو الجديد مكملة لمدة عضوية سلفه . مستبدلة بالقانون رقم 84 لسنة 1996"}, {"number": "98", "chapter": "الفصل الثانى", "text": "يعد المجلس الشعبى المحلى ولجانه مقر خاص ويلحق به العدد الضرورى من العاملين اللازمين لحسن سير العمل بالمجلس ويكون لرئيس المجلس الشعبى المحلى الإشراف عليهم وله بالنسبة إليهم السلطة المقررة لرئيس الوحدة المحلية . ويكون لرئيس المجلس الشعبى المحلى بالمحافظة بالنسبة للعاملين بالمجالس الشعبية المحلية الأخرى فى نطاق المحافظة السلطة المقررة للوزير . وتدرج بموازنة الوحدة المحلية الاعتمادات اللازمة لمواجهة نفقات المجلس وتوضع هذه الاعتمادات تحت تصرف رئيس المجلس الشعبى المحلى وتكون له ذات السلطة المقررة ماليا لرئيس الوحدة الإدارية وتكون لرئيس المجلس الشعبى المحلى للمحافظة فى هذا الشأن السلطة المالية المقررة للوزير ."}, {"number": "99", "chapter": "الفصل الثانى", "text": "يبدأ دور انعقاد المجالس الشعبية المحلية وينتهى فى المواعيد التى تحددها اللائحة التنفيذية ويكون دور انعقاد المجلس الشعبى المحلى عشرة أشهر على الأقل ويجتمع المجلس الشعبى المحلى فى المقر المخصص له اجتماعا عاديا مرة على الأقل كل شهر بدعوة من رئيسه فى الموعد الذى يحدده ويجوز دعوة المجلس الشعبى المحلى لاجتماع غير عادى فى حالة الضرورة أو عند نظر موضوع عاجل بناء على طلب رئيس المجلس أو رئيس الوحدة المحلية أو ثلث أعضاء المجلس . وفيما عدا ما ورد بشأنه نص خاص لا يكون اجتماع المجلس صحيحا إلا بحضور أغلبية أعضائه وتصدر قرارات المجلس بالأغلبية المطلقة للأعضاء الحاضرين وعند تساوى الأصوات يرجح الجانب الذى منه الرئيس ."}, {"number": "100", "chapter": "الفصل الثانى", "text": "فى حالة عدم تكامل العدد القانونى اللازم لانعقاد المجلس الشعبى المحلى للمحافظة يؤجل الاجتماع لمدة ثلاثة أيام على الأقل وسبعة أيام على الأكثر. وينبه رئيس المجلس على الأعضاء المتخلفين بحضور الاجتماع فإذا كان عدد الحاضرين فى الاجتماع الجديد أقل من العدد القانونى أخطر رئيس المجلس الشعبى المحلى أو المحافظ الوزير المختص بالإدارة المحلية بتقرير عن ذلك لعرض الأمر على مجلس الوزراء لإجراء شئونه فيه . ويخطر المجلس الشعبى المحلى للمحافظة بالنسبة للمجالس الشعبية المحلية الأخرى ."}, {"number": "100", "chapter": "الفصل الثانى", "text": "مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "101", "chapter": "الفصل الثانى", "text": "جلسات المجلس الشعبى المحلى علنية ما لم يطلب رئيس المجلس أو رئيس الوحدة المحلية أو ثلث الأعضاء جعلها سرية . وفى هذه الحالة يقرر المجلس فى جلسة سرية ما إذا كانت المناقشة فى الموضوع المطروح تستمر فى جلسة سرية أو علنية ."}, {"number": "102", "chapter": "الفصل الثانى", "text": "مع مراعاة أحكام المادة 23 من هذا القانون يحضر رئيس كل وحدة محلية جميع جلسات المجلس الشعبى المحلى للوحدة كما يحضرها من يرى رئيس الوحدة المحلية ضرورة حضورهم من مديرى الإدارات أو الأجهزة ممن تتصل اختصاصاتهم بالمسائل المعروضة على المجلس . ويجوز لأعضاء مجلس الشعب فى المحافظة حضور جلسات المجالس الشعبية المحلية فى كافة مستوياتها والمشاركة فى مناقشاتها ، ويكون لهم حق تقديم الاقتراحات والأسئلة وطلبات الاحاطة ، دون ان يكون لهم صوت معدود فى اتخاذ القرارات . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "103", "chapter": "الفصل الثانى", "text": "للمحافظ ولكل من رؤساء الوحدات المحلية ولكل عضو من أعضاء المجالس الشعبية المحلية التقدم باقتراحاتهم إلى المجلس الشعبى المحلى المختص وذلك فى المسائل الداخلة فى اختصاص المجلس وطبقا للأوضاع والإجراءات التى تحددها اللائحة الداخلية ."}, {"number": "104", "chapter": "الفصل الثانى", "text": "لكل عضو من أعضاء المجلس الشعبى المحلى أن يطلب من رئيسه إدراج موضوع معين فى جدول أعمال المجلس قبل انعقاده بأسبوع على الأقل وعلى الرئيس أن يحيل إلى اللجنة المختصة ما يقدمه الأعضاء من اقتراحات وموضوعات . وفى جميع الأحوال لا يجوز أن تناقش بالمجلس الموضوعات غير المدرجة بجدول أعمال الجلسة ."}, {"number": "105", "chapter": "الفصل الثانى", "text": "يجوز لعدد لا يقل عن خمسة من أعضاء المجلس الشعبى المحلى أن يطلبوا طرح موضوع عام يتصل بالمحافظة أو بغيرها من الوحدات المحلية فى نطاقها للمناقشة العامة. وللمجلس مناقشة هذه الموضوعات وتبادل الرأى بشأنها وذلك وفقا للأوضاع والإجراءات التى تحددها اللائحة التنفيذية ."}, {"number": "106", "chapter": "الفصل الثانى", "text": "لأعضاء المجلس الشعبى المحلى فى المركز أو المدينة أو الحى أو القربة توجيه الأسئلة وطلبات الاحاطة لرؤساء وحدات الإدارة المحلية المختصين ولمديرى الإدارات ولرؤساء الأجهزة التنفيذية المحلية ورؤساء الهيئات العامة العاملة فى نطاق الوحدة المحلية . وتسرى بشأن هذه الأسئلة وطلبات الاحاطة أحكام المادتين19 ، 20 من هذا القانون ، مع مراعاة مستوى الوحدة المحلية"}, {"number": "106", "chapter": "الفصل الثانى", "text": "مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "106 مكرر", "chapter": "الفصل الثانى", "text": "ملغاة بالقانون رقم 145 لسنة 1988 ."}, {"number": "106 مكرر", "chapter": "الفصل الثانى", "text": "1 ملغاة بالقانون رقم 145 لسنة 1981"}, {"number": "107", "chapter": "الفصل الثانى", "text": "يشكل المجلس الشعبى المحلى من بين أعضائه فى بداية كل دور انعقاد لجانا متخصصة لدراسة الموضوعات التى تدخل فى اختصاصه قبل عرضها على المجلس ولا يجوز فى غير الأحوال العاجلة عرض أى موضوع على المجلس الشعبى المحلى قبل إحالته إلى اللجنة المختصة وعرض تقريرها على المجلس فى شأنه وتنتخب كل لجنة من لجان المجلس رئيسها فى أول اجتماع لها . وتشكل بالمجلس الشعبى المحلى للمحافظة لجنة قيم تقوم بالنظر فى سلوكيات أعضاء المجالس الشعبية المحلية واقتراح الإجراء الذى يتخذ عند إخلال العضو بمقتضيات السلوك الواجب وذلك وفقا للقواعد والضوابط التى يضعها المجلس الأعلى للإدارة المحلية ."}, {"number": "108", "chapter": "الفصل الثانى", "text": "على رؤساء المصالح ومديرى رؤساء الإدارات والأجهزة التنفيذية أو غيرها من الجهات ذات الشأن فى المسائل المعروضة على لجان المجلس الشعبى المحلى حضور اجتماعاتها مع مراعاة مستوى المجلس . ويجوز للمجلس التنفيذى أو لأية لجنة من لجان المجلس الشعبى المحلى الاستعانة بمن ترى الإفادة بخبرته من ذوى الكفاءات وأن تدعو لحضور اجتماعاتها من تتصل أعمالهم بالموضوعات المعروضة عليها . ويشترك من يحضر اجتماعات اللجان من غير أعضائها فى المناقشة والدراسة دون أن يكون لهم صوت معدود فى مداولاتها . ولا يجوز اشتراك أعضاء المجالس الشعبية المحلية فى أى أعمال تنفيذية والاشتراك فى عضوية لجان ذات طابع أو اختصاص تنفيذى عدا اشتراكهم فى لجان الخدمات بالمناطق الصناعية واللجان التى تشكل لإدارة المشروعات المشتركة بين الوحدات المحلية . وتحدد اللائحة الداخلية للمجلس الشعبى المحلى أنواع لجانه وعدد أعضاء كل لجنة ونظام سير العمل بها ."}, {"number": "109", "chapter": "الفصل الثانى", "text": "تشكل لجنة دائمة فى كل مجلس من المجالس الشعبية المحلية من رؤساء لجانه وبرئاسة رئيس المجلس وتختص هذه اللجنة بإعداد جداول أعمال المجلس ودراسة وإبداء الرأى فيما يلى : أ- السياسة العامة للمجلس ومشروع الموازنة والخطة والحساب الختامى ب- الأسئلة وطلبات الاحاطة والاستجوابات المقدمة من الأعضاء . ج- كافة الأمور المتعلقة بالعضوية . د- المسائل الأخرى التى يحيلها اليها المجلس الشعبى المحلى وتتولى هذه اللجنة مباشرة اختصاصات المجلس الشعبى فيما بين أدوار انعقاده بالنسبة للمسائل الضرورية العاجلة على أن تعرض قرارات هذه اللجنة على المجلس الشعبى المحلى فى أول اجتماع تال لصدورها ليقرر ما يراه فى شأنها مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "110", "chapter": "الفصل الثانى", "text": "يجوز بقرار من المحافظ بناء على اقتراح المجلس الشعبى المحلى للمحافظة وبعد أخذ رأى وزراء التخطيط والمالية والصناعة والقوى العاملة تحديد نطاق المناطق الصناعية بالمحافظة وإنشاء لجان للخدمات بها. ويصدر من المحافظ قرار بتشكيل هذه اللجان ، بحيث يشترك فى عضويتها من يختارهم المجلس الشعبى المحلى الذى تقع فى دائرته المنطقة الصناعية ، من أعضائه ورؤساء الوحدات المحلية المختصة ورؤساء الوحدات الصناعية بالمنطقة وممثلون عن العمال ونقاباتهم بالمحافظة . مستبدلة بالقانون رقم 50 لسنة 1981 ."}, {"number": "111", "chapter": "الفصل الثانى", "text": "تتولى لجنة الخدمات بالمنطقة الصناعية تحت إشراف المجلس الشعبى المحلى المختص العمل على توفير الخدمات اللازمة للمناطق العمالية والإشراف على تنفيذ مقترحات الإصلاح والتنمية بالمنطقة كما تتولى بوجه خاص ما يأتى: 1 - إجراء الدراسات التى تتعلق باحتياجات المنطقة من الخدمات العمرانية والاجتماعية والثقافية ذات الطابع المحلى والتنسيق بينها حسب أولوياتها لتنفيذ ما يتقرر منها . 2- بحث مشاكل المنطقة ودراسة تنفيذ المقترحات التى تقدم لمعالجة هذه المشاكل . 3- تحديد المشروعات التى يتم الصرف عليها من أرباح الشركات الواقعة فى نطاق المنطقة وطبقا للأحكام المقررة فى هذا الشأن وذلك من النسبة المخصصة من الـ 10 % المخصصة من حصيلة الخدمات الاجتماعية المركزية وكذلك حصيلة الـ 5% المخصصة للخدمات الاجتماعية وخدمات الإسكان . 4- اقتراح تقرير صفة المنفعة العامة للمشروعات وتحديد العقارات المراد نزع ملكيتها والاستيلاء عليها وذلك بالنسبة للمشروعات الداخلة فى المنطقة ."}, {"number": "112", "chapter": "الفصل الثانى", "text": "تتولى لجان الخدمات بالمناطق الصناعية مباشرة اختصاصاتها المنصوص عليها فى المادة السابقة فى حدود الموارد المخصصة لذلك من بين الموارد التالية : 1- ما يخص من نصيب العاملين فى أرباح الوحدات الصناعية بالمنطقة . 2- التبرعات والهبات والوصايا المخصصة لأغراض اللجنة. 3- الموارد الأخرى التى تحدد بقرار من المجلس الشعبى المحلى للمحافظة أو مجالس إدارة الوحدات الصناعية بالمنطقة. وتدرج حصيلة هذه الموارد فى حساب خاص للصرف منها بقرار من لجنة الخدمات بالمنطقة الصناعية على الأغراض المخصصة لها تحت إشراف المجلس الشعبى المحلى المختص ."}, {"number": "112 مكرر", "chapter": "الفصل الثانى", "text": "لرئيس مجلس الوزراء اتخاذ أى إجراء أو القيام بأى عمل من شأنه التنسيق بين عدد من المحافظات فيما يتعلق بالمرافق والخدمات والمشروعات المشتركة ، وذلك بناء على عرض الوزير المختص بالإدارة المحلية وأخذ رأى المحافظين المختصين . مضافة بالقانون رقم 145 لسنة 1988 ."}, {"number": "113", "chapter": "الفصل الثانى", "text": "لمحافظ الإقليم من تلقاء نفسه أو بناء علي إقتراح المجالس الشعبية المختصة بعد أخذ رأي المجلس الشعبي المحلي للمركز وموافقة المجلس الشعبي المحلي للمحافظة أو المحافظات المختصة أن يقرر تشكيل لجنة مشتركة لإدارة المشروعات ذات النفع العام التي تشترك فيها محافظات أو مدن أو قري متجاورة . ويحدد محافظ الإقليم عدد الأعضاء الذين ينتخبهم كل مجلس شعبى محلى فى هذه اللجنة ويجب أن ينضم إلى عضوية هذه اللجنة عدد كاف من الخبراء والعاملين الذين لهم صلة بالمشروع ويختار محافظ الإقليم رئيس اللجنة ."}, {"number": "114", "chapter": "الفصل الثانى", "text": "مع مراعاة أحكام هذا القانون ولائحته التنفيذية يجوز للمجلس الشعبى المحلى أن يضع لائحة داخلية لتنظيم العمل به وكيفية ممارسته لوظيفته . ويعتمد المجلس الشعبى المحلى للمحافظة اللوائح الداخلية للمجالس الشعبية المحلية الأخرى فى نطاق المحافظة . وتسرى أحكام اللائحة النموذجية الداخلية للمجالس الشعبية المحلية التى يضعها المجلس الأعلى للإدارة المحلية على المجالس الشعبية المحلية التى لا تضع لها لائحة داخلية 0 كما تسرى تلك اللائحة فى المسائل التى لا يرد بشأنها خاص فى اللوائح الداخلية للمجالس الشعبية المحلية ."}, {"number": "115", "chapter": "الفصل الثالث", "text": "لا يجوز للوحدات المحلية الارتباط بأية مشروعات أو أعمال تتعلق بمجالات التنمية الاقتصادية أو الاجتماعية أو الطبيعية أو تمويلها أو تنفيذها بما يخالف الخطة العامة للدولة أو الخطة الاقليمية. كما لا يجوز للوحدات المحلية الارتباط بأية مشروعات استثمارية مشتركة مع رأس مال عربى أو أجنبى إلا بعد موافقة جهات التخطيط المختصة والهيئة العامة للاستثمار والمناطق الحرة ."}, {"number": "116", "chapter": "الفصل الثالث", "text": "المجالس الشعبية المحلية مسئولة عن تنمية المجتمعات المحلية تنمية شاملة أساسها مكونات وإمكانيات المجتمع المحلى وعليها كشف الفرص الاستثمارية فى نطاق كل منها وحسن توزيع الموارد على الاحتياجات حسب أولويتها الفعلية فى خططها المحلية ."}, {"number": "117", "chapter": "الفصل الثالث", "text": "تقوم الأجهزة المحلية للتخطيط بمعاونة اللجان العليا للتخطيط الاقليمى وهيئات التخطيط الاقليمى والمجالس الشعبية المحلية فى التخطيط بما يحقق حسن استغلال الإمكانيات المتاحة للوفاء باحتياجات الجماهير وتحقق التنمية الاجتماعية والاقتصادية ."}, {"number": "118", "chapter": "الفصل الثالث", "text": "تتولى كل محافظة إبلاغ مضمون توجيهات السياسية العامة والخطوط الرئيسية لخطة التنمية للدولة إلى الوحدات المحلية بدائرة المحافظة . وتحدد الوحدات المحلية احتياجاتها بحسب الأولويات المدروسة وتجمعها وتنسقها فى مشروع خطة محلية يتم إقرارها من المجلس الشعبى المحلى المختص وتبلغ للمجلس الشعبى المحلى للمحافظة قبل بدء السنة المالية بخمسة أشهر على الأقل . وتقوم أجهزة التخطيط بالمحافظة بالاشتراك مع هيئة التخطيط الإقليمى والوزارات المعنية بدراسة مشروعات التخطيط المقدمة من المجالس الشعبية المحلية فى نطاقها ويجرى التنسيق والتكامل بين مختلف القطاعات بالمحافظة لإعداد مشروع الخطة السنوية لها لعرضها مع مشروع الموازنة السنوية على المجلس الشعبى المحلى للمحافظة وكذا اللجنة العليا للتخطيط الاقليمى لإقرارها قبل بدء السنة المالية بأربعة أشهر على الأقل . وترتفع مشروعات خطط المحافظات بعد إقرارها من المجالس الشعبية المحلية واللجان العليا للتخطيط الاقليمى إلى وزير التخطيط ويتولى الوزير الربط والتنسيق بينها وبين الخطة العامة للدولة بالاتفاق مع الوزير المختص بالإدارة المحلية والوزراء المختصين ليتحقق النمو المتوازن وفق خطة التنمية العامة. وتتولى كل محافظة فى نطاقها تنفيذ الخطة المحلية المعتمدة فى المواعيد المحددة وتقوم أجهزة المتابعة فى المحافظة متابعة وتقييم التنفيذ ورفع تقارير شهرية إلى المجلس الشعبى المحلى للمحافظة والمحافظ وذلك طبقا للقواعد التى تحددها اللائحة التنفيذية . الفرع الثانى الموازنة والحساب الختامى"}, {"number": "119", "chapter": "الفصل الثالث", "text": "تحدد الأجهزة المالية المختصة بكل وحدة محلية مشروع موازنتها السنوية شاملا لإيراداتها ومصروفاتها وفقا للقواعد المعمول بها فى وضع موازنة الدولة وترفعه إلى المحافظة وذلك قبل بدء السنة المالية بخمسة أشهر على الأقل على أن يرفق بالمشروع جميع البيانات والمستندات التى بنيت عليها تقديرات الإيرادات والمصروفات ."}, {"number": "120", "chapter": "الفصل الثالث", "text": "يتولى الجهاز المالى بالمحافظة إعداد مشروع موازنة المحافظة شاملا مشروعات موازنات الوحدات المحلية فى نطاقها ويعرض المحافظ المشروع على المجلس الشعبى المحلى للمحافظة لمناقشته وإقراره قبل بدء السنة المالية بأربعة أشهر على الأقل ، وترسل كل محافظة مشروع موازناتها فور إقرار المجلس الشعبى المحلى له إلى الوزير المختص بالإدارة المحلية لبحثه مع المحافظ المختص ، ثم إرساله مشفوعا بملاحظاته إلى وزيرى المالية والتخطيط . مستبدلة بالقانون رقم 145 لسنة 1988."}, {"number": "121", "chapter": "الفصل الثالث", "text": "يجب إدراج المبالغ الآتية بمشروعات موازنات المحافظات إذا أغفلت كلها أو بعضها: 1- الالتزامات التى تكون المحافظة أو إحدى وحدات الإدارة المحلية فى نطاقها ملتزمة بها . 2- الاستخدامات التى يفرضها هذا القانون أو أى قانون آخر . 3- مصروفات الإدارة أو الصيانة اللازمة لحسن سير المرافق والمنشآت أو الأعمال التى تتولاها المحافظة أو حدات الإدارة المحلية فى نطاق المحافظة. مستبدلة بالقانون رقم 145 لسنة 1988."}, {"number": "122", "chapter": "الفصل الثالث", "text": "تدرج موازنة كل محافظة فى قسم خاص بالموازنة العامة للدولة وتعتبر جزءا منها ويسرى عليها ما يسرى على الموازنة العامة للدولة من أحكام ."}, {"number": "123", "chapter": "الفصل الثالث", "text": "على الأجهزة المالية المختصة بالمحافظة تقديم مشروعات الحسابات الختامية السنوية للمحافظة والوحدات المحلية التابعة لها إلى كل من وزارة المالية والجهاز المركزى للمحاسبات وذلك فى المواعيد ووفقا للقواعد والإجراءات المنصوص عليها فى قانون الموازنة العامة للدولة ."}, {"number": "124", "chapter": "الفصل الثالث", "text": "يعرض المحافظ مشروع الحساب الختامى السنوى للمحافظة شاملا لمشروعات الحسابات الختامية للوحدات المحلية فى نطاقها على المجلس الشعبى المحلى للمحافظة مرفقا بها ملاحظات وزارة المالية وتقارير الجهاز المركزى للمحاسبات وذلك فى المواعيد ووفقا للقواعد والإجراءات التى يصدر بها قرار من وزير المالية . ويقدم المحافظ مشروعات الحسابات الختامية بعد إقرارها من المجلس الشعبى المحلى للمحافظة الى وزير المالية ويعرض الحساب الختامى لكل محافظة فى قسم خاص من الحساب الختامى للدولة ويسرى عليه ما يسرى على هذا الحساب من أحكام الفرع الثالث الضرائب والرسوم والموارد المحلية"}, {"number": "125", "chapter": "الفصل الثالث", "text": "تبين اللائحة التنفيذية القواعد الخاصة بتحديد أسس وإجراءات حساب جميع الرسوم ذات الطابع المحلى وطريقة التظلم منها وإجراءات تخفيضها . ويجوز أن تتضمن هذه اللائحة عدة نظم لأسس وإجراءات حساب جميع هذه الرسوم ولكل مجلس من المجالس الشعبية المحلية أن يختار منها النظام الذى يلائم ظروف الوحدة المحلية ."}, {"number": "126", "chapter": "الفصل الثالث", "text": "يتبع فى تحصيل الضرائب والرسوم المقررة للوحدات المحلية وفى الإعفاء منها وفى سقوطها بالتقادم القواعد المقررة بشأن الضرائب والرسوم العامة . وتعتبر ديون تلك الضرائب والرسوم ديونا ممتازة على جميع أموال المدينين بها وتستوفى بعد المصاريف القضائية والضرائب الحكومية مباشرة . ويجوز أن تتولى الأجهزة الحكومية المختصة ربط وتحصيل الضرائب والرسوم التى تخص الوحدات المحلية وأداء الحصيلة إليها وذلك بعد موافقة المجلس الشعبى المحلى للمحافظة."}, {"number": "127", "chapter": "الفصل الثالث", "text": "لا يجوز منح التزام استغلال أى مرفق من المرافق العامة المحلية أو أى مصدر من مصادر الثروة الطبيعية فيما عدا البترول والثروة المعدنية فى نطاق اختصاص الوحدة الحلية إلا بعد الحصول على موافقة المجلس الشعبى المحلى المختص ."}, {"number": "128", "chapter": "الفصل الثالث", "text": "لا يجوز للمجلس الشعبى المحلى قبول التبرعات المقيدة بشرط يخرج تنفيذه على سلطة المجلس أو أن يغير تخصيصها إلا بموافقة المحافظ ، ويجب موافقة رئيس مجلس الوزراء على قبول التبرعات والمساعدات التى تقدمها هيئات أو أشخاص أجنبية مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "129", "chapter": "الفصل الثالث", "text": "لا يجوز لوحدات الإدارة المحلية إبرام أى قرض أو الارتباط بأى مشروع غير وارد فى الخطة أو الموازنة إذا كان يترتب عليه إنفاق مبالغ فى فترة مقبلة إلا بعد موافقة مجلس الشعب وذلك مع مراعاة أحكام المادة 15 ."}, {"number": "130", "chapter": "الفصل الثالث", "text": "فيما عدا ما ورد بشأنه نص خاص . تسرى على الوحدات المحلية القوانين واللوائح المالية المطبقة فى الحكومة وتسرى على الوحدات المحلية القواعد المقررة لأموال الحكومة وتعفى تلك الوحدات من جميع الضرائب والرسوم التى تعفى منها الحكومة ."}, {"number": "131", "chapter": "الفصل الرابع", "text": "يهدف الإشراف والرقابة على أعمال المجالس الشعبية المحلية وأجهزتها التنفيذية إلى تحقيق التناسق والترابط بينهما بما يتفق وأهداف السياسة العامة للدولة وكذلك تقديم المشورة والمساعدة للمجالس الشعبية المحلية بما يكفل تحقيق أهداف نظام الإدارة المحلية ."}, {"number": "132", "chapter": "الفصل الرابع", "text": "تعتبر قرارات المجالس الشعبية المحلية نافذة فى حدود الاختصاصات المقررة لها فى هذا القانون وفى إطار الخطة العامة للدولة والموازنة المعتمدة وبمراعاة القوانين واللوائح . ويجوز للمحافظ أو رئيس الوحدة المحلية المختصة الاعتراض على أى قرار يصدر من المجلس الشعبى المحلى بالمخالفة للخطة العامة للدولة أو الموازنة المعتمدة أو ينطوى على أية مخالفة للقوانين أو اللوائح أو يخرج عن اختصاصات المجلس المحددة فى هذا القانون وله فى هذه الحالة إعادة هذا القرار الى المجلس الشعبى المحلى الذى أصدره مشفوعا بملاحظاته والأسباب التى يبنى عليها اعتراضه ، وذلك خلال خمسة عشر يوما من تاريخ إبلاغه القرار . فإذا أصر المجلس الشعبى المحلى للمحافظة على قراره ، عرض الوزير المختص بالإدارة المحلية الأمر على مجلس الوزراء خلال ثلاثين يوما من تاريخ إبلاغه به . ويقوم مجلس الوزراء بالبت فى القرارات المعترض عليها خلال ثلاثون يوما من تاريخ عرض الأمر عليه ، ويكون قرار المجلس فى هذا الشأن نهائيا. وفى حالة إصرار أى من المجالس الشعبية المحلية للوحدات المحلية الأخرى على قراره ، يخطر المحافظ المختص رئيس المجلس الشعبى المحلى للمحافظة ويعرض الأمر على الوزير المختص بالإدارة المحلية ، ويقوم الوزير بالبت فى القرارات المعترض عليها خلال ثلاثين يوما من تاريخ عرضها عليه ، ويكون قراره فى هذا الشأن نهائيا ."}, {"number": "133", "chapter": "الفصل الرابع", "text": "يتولى مجلس الوزراء الرقابة على أعمال المحافظات وتقييم أدائها لأعمالها طبقا لأحكام هذا القانون ولائحته التنفيذية ، وتستهدف هذه الرقابة ما يلى : 1- مراعاة تنفيذ السياسة العامة والخطة العامة للدولة . 2- تحقيق المحافظات للأهداف المقررة لها ، وتقييم أدائها وتنفيذها للتوجيهات التى تكفل التنسيق بين المحافظات والوزارات. 3- ولرئيس مجلس الوزراء بناء على عرض الوزير المختص بالإدارة المحلية وبعد أخذ رأى المحافظ المختص أن يتخذ أى أجراء أو أن يقوم بأى عمل كان يتعين على أى من المجالس الشعبية المحلية القيام به وفقا للخطة العامة للدولة ، أو الموازنة المعتمدة ، أو تفرضه القوانين واللوائح ، إذا كان امتناعه عن ذلك غير قائم على سبب يقره القانون وكان قد تم تنبيهه الى القيام به ."}, {"number": "133 مكرر", "chapter": "الفصل الرابع", "text": "يقدم الوزير المختص بالإدارة المحلية لرئيس مجلس الشعب تقريرا سنويا عن نشاط وإنجازات المجالس الشعبية المحلية يتضمن ما تم تنفيذه من خطط التنمية والموازنات الخاصة بكل محافظة ، وبيانا بالأسئلة وطلبات الاحاطة والاقتراحات المهمة التى تمت مناقشتها فى المجالس الشعبية المحلية والقرارات التى صدرت بشأنها ."}, {"number": "مضافة بقانون رقم", "chapter": "الفصل الرابع", "text": "145 لسنة 1988"}, {"number": "134", "chapter": "الفصل الرابع", "text": "لكل من الوزراء في نطاق اختصاص وزاراته : 1- إبلاغ المحافظات بالخطة العامة للدولة ومتابعة تنفيذها من الناحية الفنية وكذلك إبلاغ الوحدات المحلية بما يراه من إرشادات وتوجيهات فنية تؤدي إلي حسن سير الخدمات في المرافق العامة بما يتفق مع السياسة العامة للدولة وخاصة فيما يتعلق بالسياسة الزراعية والتركيب المحصولي وشئون التمويل وتسعير السلع . 2- وضع خطة سنوية بالاتفاق مع المحافظين المعنيين لتوزيع وتنسيق العمالة الفنية بين المحافظات وفق احتياجاتها وتبليغ هذه الخطة إلي المحافظين لاتخاذ الإجراءات اللازمة لتنفيذها. 3- المساهمة مع الوحدات المحلية في الأعمال والمشروعات الداخلة في اختصاص هذه الوحدات بعد الاتفاق معها ."}, {"number": "135", "chapter": "الفصل الرابع", "text": "يتولى المحافظ التفتيش على الأجهزة التنفيذية للوحدات المحلية فى نطاق المحافظة والمرافق الخاضعة لإشرافها وله أن يكلف بإجراء هذا التفتيش أجهزة الرقابة المختصة أو من يختاره من الفنيين والإداريين المختصين من العاملين المدنيين بالمحافظة ."}, {"number": "136", "chapter": "الفصل الرابع", "text": "تتولى كل من وزارة المالية والجهاز المركزى للمحاسبات طبقا لقانون الموازنة العامة ، وقانون الجهاز المركزى للمحاسبات مراجعة حسابات الوحدات المحلية بالنسبة لإيراداتها ومصروفاتها . ويكون ممثلو وزارة المالية فى هذه الوحدات مسئولين عن صحة هذه الحسابات ومطابقتها للقوانين واللوائح والتعليمات المالية المعمول بها وذلك على النحو الذى تفصله اللائحة التنفيذية . ويخطر الجهاز المركزى للمحاسبات المجلس الشعبى المحلى للمحافظة والمحافظ المختص بالتقارير التى يعدها عن حسابات المحافظة والوحدات المحلية الأخرى الخاضعة لإشرافها."}, {"number": "137", "chapter": "الفصل الرابع", "text": "يتولى مجلس الدولة الإفتاء فى الموضوعات القانونية المتعلقة بوحدات الإدارة المحلية . كما تتولى إدارة قضايا الحكومة مباشرة الدعاوى التى تكون هذه الوحدات طرفا فيها . وتتم إحالة الموضوعات القانونية المشار إليها من رئيس المجلس الشعبى المحلى للمحافظة أو من المحافظ المختص أو من ينيبه بحسب الأحوال ."}, {"number": "138", "chapter": "الفصل الخامس", "text": "يكون لكل مديرية من مديريات المحافظة هيكل تنظيمى مستقل يشمل جميع العاملين فى مجال اختصاصها فى نطاق المحافظة ، ويكون العاملون فى كل مديرية من هذه المديريات وحدة وظيفية واحدة ، مع مراعاة تخصصاتهم وذلك طبقا للقواعد التى تحددها اللائحة التنفيذية . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "139", "chapter": "الفصل الخامس", "text": "يصدر بالتعيين أو الندب لشغل مناصب السكرتيرين العامين والسكرتيرين العامين المساعدين ورؤساء المدن والأحياء ، كما يصدر بنقلهم من مناصبهم بين وحدات الإدارة المحلية ونقلهم إلى أجهزة الإدارة المحلية المختلفة قرار من رئيس مجلس الوزراء بالاتفاق مع المحافظات المختصين. ويصدر بالتعيين والندب لشغل مناصب رؤساء القرى ونقلهم بين وحدات الحكم المحلى الداخلة فى نطاق المحافظة ، قرار من المحافظة. مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "140", "chapter": "الفصل الخامس", "text": "مع مراعاة الأحكام المطبقة على العاملين المدنيين بالدولة تعلن وحدات الإدارة المحلية عن الوظائف الخالية بها والتى يكون التعيين فيها بقرار من المحافظ ويتضمن الإعلان البيانات المتعلقة بالوظيفة وشروط شغلها . ويحدد المحافظ الوظائف التى يكون شغلها بامتحان وتلك التى تشغل بدون امتحان ، ويكون التعيين فى الوظائف التى تشغل بامتحان بحسب الأسبقية الواردة بالترتيب النهائى لنتائج الامتحان ، وعند التساوى فى الترتيب تكون الأولوية فى التعيين لأبناء المحافظة . ويجوز بقرار من المحافظ أن يكون الامتحان مقصورا على أبناء المحافظة ويعتبر من أبناء المحافظة من يقيم بدائرتها إقامة عادية."}, {"number": "141", "chapter": "الفصل الخامس", "text": "يجوز للمحافظ فى حدود الموازنة المعتمدة أن يشغل بعض الوظائف التى تقتضى تفرغ شاغليها بطريق التعاقد مقابل مكافأة شاملة يحددها العقد وذلك وفقا للقواعد العامة الصادرة فى هذا الشأن . كما يجوز للمحافظ أن يعين بأقسام الوحدة بطريق التعاقد صناعا ممتازين للأعمال الفنية التى تقتضى مهارة أو خبرة خاصة وذلك نظير أجر يحدده العقد ."}, {"number": "142", "chapter": "الفصل الخامس", "text": "تنقل بقوة القانون الاعتمادات المالية الخاصة بالعاملين فى الجهات التى نقلت اختصاصاتها بمقتضى هذا القانون إلى وحدات الإدارة المحلية إلى الموازنات الخاصة بهذه الوحدات ."}, {"number": "143", "chapter": "الفصل الخامس", "text": "تسرى فيما لم يرد فى شأنه نص فى هذا القانون الأحكام والقواعد الخاصة بالعاملين المدنيين فى الدولة على العاملين المدنيين بوحدات الإدارة المحلية."}, {"number": "144", "chapter": "الفصل السادس", "text": "لا يجوز حل المجالس الشعبية المحلية بإجراء شامل ، كما لا يجوز أن يحل المجلس الشعبى المحلى مرتين لسبب واحد. مستبدلة بالقانون رقم 50 لسنة 1981"}, {"number": "145", "chapter": "الفصل السادس", "text": "يصدر بحل المجلس الشعبى المحلى للمحافظة أو لغيرها من وحدات الإدارة المحلية قرار من مجلس الوزراء بناء على ما يعرضه الوزير المختص بالإدارة المحلية لأسباب تقتضيها المصلحة العامة ويقدرها مجلس الوزراء . وينشر القرار الصادر بحل المجلس الشعبى المحلى فى الجريدة الرسمية ويخطر به مجلس الشعب خلال أسبوعين من تاريخ صدوره . مستبدلة بالقانون رقم 50 لسنة 1981."}, {"number": "146", "chapter": "الفصل السادس", "text": "يشكل فى القرار الصادر بحل المجلس الشعبى المحلى مجلس مؤقت بناء على اقتراح المحافظ المختص ويجب أن يضم تشكيله عددا كافيا من قيادات التنظيمات المحلية ويتولى المجلس المؤقت مباشرة اختصاصات المجلس المنحل بالنسبة للمسائل الضرورية والعاجلة حتى يتم تشكيل المجلس الشعبى المحلى الجديد ويجب إجراء الانتخابات لتشكيل هذا المجلس الجديد خلال الستين يوما التالية لصدور قرار الحل . وتعرض القرارات التى يتخذها المجلس المؤقت على المجلس الجديد فى أول جلسة يعقدها بعد تشكيله لاتخاذ ما يراه بشأنها وذلك طبقا للقواعد التى تحددها اللائحة التنفيذية."}]};